		["debugBreakpoint"] = "Toggle breakpoint (F9)",
		["debugCallbackHelp"] = "To debug an OnEvent handler defined in your code, use :SetScript(\"OnEvent\", ...) or :HookScript(\"OnEvent\", ...), set a breakpoint inside the callback and start Debug current script once. After registration, incoming events run the callback in the debugger. CreateFrame and _G.CreateFrame both work. Up to 50 events wait while paused; newer events are dropped when the queue is full, and nil arguments are preserved. Stopping restores the previous SetScript handler if the debug handler is still installed. HookScript hooks cannot be removed, so stopped debug hooks become inactive.",
		["debugClearBreakpoints"] = "Clear breakpoints",
		["debugContinue"] = "Continue (F5)",
		["debugDrawer"] = "Show or hide debug terminal",
		["debugEvents"] = "Debug configured events",
		["debugEventsHelp"] = "Event debugging listens for enabled custom events and PLAYER_LOGIN if configured. It does not replay startup or login. Use Debug current script to test the code immediately.",
		["debugHelp"] = "Click a line number to toggle a breakpoint. Start debugging from the debugger button beside Run, or choose the configured events. F5 continues, F10 steps over, F11 steps into script functions, Shift+F5 stops. The terminal can read and change locals at the paused line. Hover a variable in the editor to inspect it. New events wait in a bounded queue while WoW continues. Breakpoints are saved per script across reloads and follow their lines when text is inserted or removed. Markers on non-executable lines are retained but cannot pause execution; deleting a whole code line can remove its breakpoint.",
		["debugHelperHelp"] = "F10 steps over helper calls; F11 enters saved helper modules loaded through requireHelper. If the editor matches the executed source, the debugger uses the normal editor. If an unsaved draft differs, it opens a read-only snapshot and preserves the draft. Save helper changes before starting a new debug session.",
		["debugInspectUnavailable"] = "No value in the current scope",
		["debugLimits"] = "Debugging uses source snapshots. Editing the active script stops debugging; breakpoints are retained and adjusted to the changed lines. Only OnEvent callbacks registered with :SetScript or :HookScript are queued. Direct pcall/xpcall calls run without stepping. Native functions cannot be stepped into, and callbacks that must return synchronously to a native function, such as sorting callbacks, cannot pause. Unsupported pauses cause errors. Instrumented returns do not preserve Lua tail-call optimization.",
		["debugNoEvents"] = "Add an event in the script settings first.",
		["debugPaused"] = "Breakpoint reached",
		["debugProbeBindingsError"] = "Invalid debugger variable binding.",
		["debugProbeBindingsHelp"] = "For this test, the optional third argument to breakpoint() exposes real local variables: { amount = { get = function() return amount end, set = function(value) amount = value end } }. The terminal reads through get and assignments call set. Without set, the variable is read only. These bindings apply only to the current checkpoint and event invocation; queued events keep their own locals. Automatic scope capture and source instrumentation are not implemented yet.",
		["debugProbeError"] = "Debugger test error",
		["debugProbeEvaluate"] = "Evaluate",
		["debugProbeFinished"] = "Run complete",
		["debugProbeHelp"] = "/lwdebug EVENT arms the current code; /lwdebug fire queues a test event; /lwdebug step advances; /lwdebug stop aborts and clears the queue. Add breakpoint(\"label\", {value=value}) to inspect supplied variables. F10 advances to the next checkpoint while this panel or the editor is active. Events wait in order, up to 50 pending. WoW continues running; tables remain live references. Automatic line stepping, F11 and helper imports are not supported. Checkpoints inside pcall/xpcall are unsupported. Secret values are masked in the list; secret strings may be displayed directly in the tooltip.",
