		["debugProbeTerminal"] = "Debug terminal",
		["debugProbeTerminalHelp"] = "The test terminal reads variables supplied to breakpoint() and the script environment. Explicit bindings change real locals; other scalar assignments stay in the console. Table changes and function calls affect the script.\n\nEnter: evaluate and clear the input.\nAlt+Up/Down: recall up to 100 commands.\n/lwdebug eval EXPRESSION also evaluates code. New output scrolls to the bottom; 100 output lines are retained.\n\nErrors leave the script paused. Secret values stay masked.",
