		["debugScheduleAlways"] = "Every login/reload",
		["debugScheduleCancel"] = "Cancel scheduled debugging",
		["debugScheduleHelp"] = "Use the bug menu to schedule one saved script for the next login/reload, once by default or every time. ADDON_LOADED means LuaWorkbench itself has loaded; PLAYER_LOGIN runs at login. Saved code, helpers and breakpoints are used; unsaved drafts are preserved. The editor starts minimized without taking focus. Normal automatic execution of this script is suppressed while the startup debugger owns it, including on compilation failure. Stop releases that ownership. Stopping a session does not cancel a recurring schedule; use Cancel scheduled debugging. WoW keeps running, and addons loaded before LuaWorkbench cannot be debugged retroactively.",
