		["helperConsumerHelp"] = "In another script, import the helper under a local name. Your own local function can use the same function name without replacing the helper:",
		["helperCycle"] = "Circular helper dependency:",
		["helperDuplicate"] = "This module name is already used:",
		["helperEnabled"] = "Expose as a helper module",
		["helperHelp"] = "Save a script, open its settings and expose it as a helper module with a unique name such as MyTools. The module name is separate from its display title; names differing only in case conflict. A helper returns a table of functions or values. It runs only when requireHelper requests it. Each manual or automatic run gets a fresh module cache; repeated and transitive imports within that run share the same table. Missing modules, duplicate names, cycles and non-table return values produce errors. Helper variables stay in the internal environment; writing to _G is always an explicit choice. Example helper:",
		["helperInlineHelp"] = "A helper must end with return tools (or return another table). Put the functions you want to share in that table. requireHelper returns this table so another script can call its functions. Without a table return, the import fails. Only saved code runs, when requested; enabling this option does not run it.",
