		["queryLuaFormat"] = "Code formatieren",
		["queryLuaHelp"] = "Wird sofort mit Zugriff auf WoW-APIs ausgeführt. Helfer: addon, print(...). Nur vertrauten Code ausführen; Endlosschleifen können das Spiel einfrieren.",
		["queryLuaOutput"] = "Output",
