		["removeFolder"] = "Ordner entfernen (Skripte behalten)",
		["rename"] = "Umbenennen",
		["resetColor"] = "Diese Farbe zurücksetzen",
		["resetColors"] = "Alle Farben zurücksetzen",
		["resizePanes"] = "Ziehen, um Code und Ausgabe aufzuteilen",
		["restore"] = "Editor wiederherstellen",
		["restoreDrafts"] = "Ungespeicherte Entwürfe nach Reload wiederherstellen",
		["revertSaved"] = "Auf gespeicherten Stand zurücksetzen",
		["rootFolder"] = "Kein Ordner",
		["runOnEvent"] = "Bei Event ausführen",
		["runOnLogin"] = "Beim Login / UI-Reload",
		["runOnStartup"] = "Beim Laden von LuaWorkbench",
		["runWithF5"] = "Mit F5 im Editor ausführen",
		["save"] = "Speichern",
		["saveAll"] = "Alle Skripte speichern",
		["saveBeforeAutoRun"] = "Dieses Skript vor der automatischen Ausführung speichern.",
		["savedCodeOnly"] = "Automatisch läuft der zuletzt gespeicherte Code.",
		["scriptSettings"] = "Skripteinstellungen",
		["scriptSettingsHelp"] = "Das Zahnrad neben dem Skriptnamen öffnet dessen Einstellungen. Das blaue Automatik-Symbol in der Skript-Liste zeigt aktive Auslöser; ein Klick öffnet die Einstellungen dieses Skripts. Der Ungespeichert-Punkt bleibt unabhängig davon. Automatische Ausführung und Leeren der Ausgabe vor einem Lauf werden pro Skript eingestellt.",
		["searchSnippets"] = "Skripte und Code durchsuchen",
		["secretDumpChat"] = "Secret-Dumps im Blizzard-Chat",
		["sessionErrors"] = "Sitzungsfehler",
		["snippetName"] = "Skript-Name",
		["snippets"] = "Skripte",
		["startupDescription"] = "Läuft beim Laden von LuaWorkbench (ADDON_LOADED), früh im UI-Ladevorgang.",
		["syntaxColors"] = "Syntaxfarben",
		["syntaxHelp"] = "Eine Farbe wählen oder sechs Hex-Ziffern eingeben. Die gemeinsame Codeanalyse unterscheidet lokale Variablen, Parameter, Funktionsdefinitionen und nichtlokale Namen, soweit statisch erkennbar. Die Farben sagen nicht aus, ob ein globaler Name existiert oder der Code korrekt ist. Zurücksetzen stellt die Standardfarben wieder her.",
		["tableInspectTool"] = "Tabelleninspektor öffnen (/tableinspect, /tinspect).",
		["textSnippetCode"] = "Codefragment",
		["textSnippetDelete"] = "Textbaustein löschen",
		["textSnippetDeleteConfirm"] = "Diesen Textbaustein löschen?",
		["textSnippetEmpty"] = "Keine Textbausteine gefunden.",
		["textSnippetInsert"] = "Textbaustein einfügen",
		["textSnippetName"] = "Name",
		["textSnippetNew"] = "Neuer Textbaustein",
		["textSnippetRequired"] = "Einen Namen und ein Codefragment eingeben.",
		["textSnippetSave"] = "Textbaustein speichern",
		["textSnippetSearch"] = "Namen und Code durchsuchen",
		["textSnippetTargetChanged"] = "Das Skript wurde geändert. Die Textbaustein-Bibliothek erneut öffnen, um die Einfügeposition festzulegen.",
		["textSnippets"] = "Textbausteine",
		["textSnippetsHelp"] = "Textbausteine sind wiederverwendbare Codefragmente, die getrennt von ausführbaren Skripten gespeichert werden. Über Textbausteine öffnest du die Bibliothek zum Auswählen, Erstellen, Suchen, Bearbeiten, Speichern oder Löschen. Einfügen setzt das Fragment an die beim Öffnen erfasste Cursorposition und führt keinen Code aus. Vorhandenen Code kannst du kopieren und im Bibliothekseditor als neuen Textbaustein einfügen. Die Suche berücksichtigt Namen und gespeicherten Code.",
		["thickOutline"] = "Dicke Kontur",
