		["minimapToggle"] = "Mostrar / ocultar botón del minimapa",
		["minimize"] = "Minimizar",
		["minimizedOutput"] = "Mostrar salida nueva al minimizar",
		["minimizedOutputHelp"] = "La vista previa opcional bajo la barra minimizada muestra una cantidad configurable de las últimas líneas nuevas. Su altura se adapta a las líneas visibles y la cabecera indica cuántas se muestran. Se desvanece tras unos segundos; púlsala para restaurar el editor. Las ráfagas se agrupan y la salida completa permanece en el editor. Desactivada por defecto, con tres líneas de vista previa.",
		["minimizedOutputLines"] = "Líneas de vista previa minimizada",
		["monochrome"] = "Contorno monocromo",
		["moveTo"] = "Mover a carpeta…",
		["navigationBack"] = "Volver",
		["navigationHelp"] = "F12 abre una declaración local o una exportación de módulo reconocible estáticamente. Alt+Izquierda vuelve al script, cursor y desplazamiento anteriores. Se consideran variables locales, parámetros y ámbitos. La navegación admite alias locales explícitos de requireHelper con nombres literales y exportaciones de tablas sencillas. No deduce claves dinámicas, definiciones generadas, metatablas ni resoluciones globales arbitrarias. El código grande o incompleto se analiza de forma conservadora; no es un servidor de lenguaje.",
		["navigationLine"] = "Línea %d",
		["navigationMissingScript"] = "El script anterior ya no existe.",
		["navigationNotFound"] = "No se encontró aquí una definición estática inequívoca.",
		["navigationSavedHelp"] = "Este módulo tiene cambios sin guardar. Se muestra en modo de solo lectura la versión guardada que usa requireHelper; el borrador se conserva. Cierra esta vista o usa Alt+Izquierda para volver.",
