		["outputWindow"] = "Ventana de salida",
		["outputWindowHelp"] = "Elige la disposición en Opciones > Salida o en el menú de la ventana de salida. Solo Flotante permite mover la ventana por su título. Las ventanas acopladas solo se pueden redimensionar desde la esquina inferior derecha. Acoplada sigue al editor; se guardan su posición y tamaño. Elige Integrada para devolverla al editor.",
