		["scriptSettings"] = "Opciones del script",
		["scriptSettingsHelp"] = "El engranaje junto al nombre abre las opciones del script. El símbolo azul en la lista indica que hay activadores automáticos; púlsalo para abrir sus opciones. El punto de cambios sin guardar es independiente. La ejecución automática y el vaciado de salida se configuran por script.",
