		["syntaxColors"] = "Colores de sintaxis",
		["syntaxHelp"] = "Elige un color o escribe seis dígitos hexadecimales. El análisis compartido distingue variables locales, parámetros, definiciones de función y nombres no locales cuando puede reconocerlos estáticamente. Los colores no indican si un nombre global existe ni si el código es correcto. Restablecer recupera los colores predeterminados.",
