		["textSnippetTargetChanged"] = "El script cambió. Vuelve a abrir la biblioteca de fragmentos para elegir la posición de inserción.",
		["textSnippets"] = "Fragmentos de código",
		["textSnippetsHelp"] = "Los fragmentos son código reutilizable guardado por separado de los scripts ejecutables. Abre Fragmentos de código para elegir, crear, buscar, editar, guardar o eliminar uno. Insertar lo añade en la posición del cursor registrada al abrir la biblioteca, sin ejecutar código. Para guardar código existente como fragmento, cópialo y pégalo en el editor de la biblioteca. La búsqueda incluye nombres y código guardado.",
