	frFR = {
		["addEvent"] = "Ajouter un événement",
		["apiAll"] = "Tout",
		["apiArguments"] = "Arguments",
		["apiCallbacks"] = "Fonctions de rappel",
		["apiConstants"] = "Constantes",
		["apiCopyFunction"] = "Copier la fonction",
		["apiCopyName"] = "Copier le nom",
		["apiDefault"] = "Valeur par défaut",
		["apiEnums"] = "Énumérations",
		["apiEvents"] = "Événements",
		["apiFields"] = "Champs",
		["apiFunction"] = "Fonction de l’API Blizzard",
		["apiFunctions"] = "Fonctions / méthodes",
		["apiHelp"] = "Aide et coloration de l’API Blizzard",
		["apiIndexing"] = "Préparation de la recherche intégrale : %d / %d · recherche par nom disponible",
		["apiOptional"] = "facultatif",
		["apiOther"] = "Autres",
		["apiPayload"] = "Arguments de l’événement",
		["apiPending"] = "La documentation sera chargée après le combat.",
		["apiRestrictions"] = "Restrictions / valeurs secrètes",
		["apiResults"] = "%d résultats · %d affichés",
		["apiReturns"] = "Valeurs renvoyées",
		["apiSearch"] = "Rechercher des noms d’API, descriptions et paramètres",
		["apiStructures"] = "Structures",
		["apiSystems"] = "Objets / systèmes",
		["apiTypes"] = "Types",
		["apiUnavailable"] = "Impossible de charger la documentation de l’API Blizzard. Rouvrez l’éditeur pour réessayer.",
		["autoIndent"] = "Indentation automatique",
		["autoPairs"] = "Fermer les parenthèses et guillemets",
		["autoRunHelp"] = "Les exécutions automatiques utilisent le code enregistré, jamais les modifications non enregistrées. Le démarrage intervient une fois au chargement de LuaWorkbench (ADDON_LOADED), la connexion une fois à PLAYER_LOGIN, même après un rechargement. Si les deux sont activés, le script tourne aux deux étapes. Un événement personnalisé le lance à chaque occurrence, même éditeur fermé. Tout est désactivé par défaut ; activer une option ne lance rien immédiatement.",
		["autocomplete"] = "Complétion du code et aide aux paramètres",
		["autocompleteHelp"] = "Enter / Tab : insérer · Échap : fermer · Ctrl+Espace : suggestions",
		["automaticRun"] = "Exécution automatique",
		["clearErrors"] = "Effacer les erreurs",
		["clearOnRun"] = "Vider à chaque exécution",
		["clearOutputAction"] = "Effacer",
		["clearSearch"] = "Effacer la recherche",
		["colorCall"] = "Appels de fonctions",
		["colorComment"] = "Commentaires",
		["colorFunctionName"] = "Définitions de fonction",
		["colorGlobalVariable"] = "Noms non locaux",
		["colorIdentifier"] = "Noms / identifiants",
		["colorKeyword"] = "Mots-clés",
		["colorLiteral"] = "true / false / nil",
		["colorLocalVariable"] = "Variables locales",
		["colorNumber"] = "Nombres",
		["colorOperator"] = "Opérateurs",
		["colorParameter"] = "Paramètres de fonction",
		["colorPunctuation"] = "Parenthèses et ponctuation",
		["colorString"] = "Chaînes de caractères",
		["confirmDelete"] = "Supprimer cet script ?",
		["confirmRevert"] = "Abandonner les modifications et restaurer la dernière version enregistrée ?",
		["copyOutputAction"] = "Copier",
		["copyOutputHint"] = "Sélectionner le texte, puis appuyer sur Ctrl+C pour copier.",
		["cursorPosition"] = "Lig %d, Col %d",
		["customEventHelp"] = "Saisissez un événement WoW, puis appuyez sur Entrée ou + pour l’ajouter. Chaque événement peut être activé ou retiré séparément. Les événements invalides sont refusés. Dans le script, event contient son nom et ... ses arguments. Le démarrage transmet les arguments de ADDON_LOADED. Enregistrez le script avant toute exécution automatique.",
		["customEvents"] = "Événements personnalisés",
		["customize"] = "Personnaliser…",
		["debugBreakpoint"] = "Activer ou désactiver un point d’arrêt (F9)",
		["debugCallbackHelp"] = "Pour déboguer un gestionnaire OnEvent défini dans le code, utilisez :SetScript(\"OnEvent\", ...) ou :HookScript(\"OnEvent\", ...), placez un point d’arrêt dans le rappel et lancez une fois Déboguer le script actuel. Après son inscription, les événements reçus exécutent le rappel dans le débogueur. CreateFrame et _G.CreateFrame fonctionnent tous deux. Jusqu’à 50 événements attendent pendant une pause ; les nouveaux sont ignorés si la file est pleine et les arguments nil sont conservés. À l’arrêt, le gestionnaire SetScript précédent est rétabli si celui du débogueur est toujours installé. Les hooks HookScript ne peuvent pas être retirés et deviennent inactifs à l’arrêt.",
		["debugClearBreakpoints"] = "Effacer les points d’arrêt",
		["debugContinue"] = "Continuer (F5)",
		["debugDrawer"] = "Afficher ou masquer la console de débogage",
		["debugEvents"] = "Déboguer les événements configurés",
		["debugEventsHelp"] = "Le débogage des événements attend les événements personnalisés activés et PLAYER_LOGIN si configuré. Il ne rejoue ni le démarrage ni la connexion. Utilisez Déboguer le script actuel pour tester le code immédiatement.",
		["debugHelp"] = "Cliquez sur un numéro de ligne pour activer ou désactiver un point d’arrêt. Lancez le débogage avec le bouton à côté d’Exécuter, ou choisissez les événements configurés. F5 continue, F10 passe à l’instruction suivante, F11 entre dans les fonctions du script et Shift+F5 arrête. La console peut lire et modifier les variables locales à la ligne en pause. Survolez une variable dans l’éditeur pour l’inspecter. Les nouveaux événements attendent dans une file limitée pendant que WoW continue. Les points d’arrêt sont enregistrés par script entre les rechargements et suivent leurs lignes lors de l’ajout ou de la suppression de texte. Les marqueurs sur des lignes non exécutables restent visibles sans provoquer de pause ; supprimer une ligne entière peut retirer son point d’arrêt.",
		["debugHelperHelp"] = "F10 passe les appels de modules ; F11 entre dans les modules enregistrés chargés par requireHelper. Si l’éditeur correspond au code exécuté, le débogueur utilise l’éditeur normal. Si un brouillon non enregistré diffère, il ouvre une copie en lecture seule et conserve le brouillon. Enregistrez les changements du module avant une nouvelle session.",
		["debugInspectUnavailable"] = "Aucune valeur dans la portée actuelle",
		["debugLimits"] = "Le débogueur utilise des copies du code. Modifier le script actif arrête le débogage ; les points d’arrêt sont conservés et adaptés aux lignes modifiées. Seuls les rappels OnEvent inscrits via :SetScript ou :HookScript sont mis en file. Les appels directs à pcall/xpcall s’exécutent sans pas à pas. Il est impossible d’entrer dans les fonctions natives ; les rappels devant revenir de manière synchrone à une fonction native, comme ceux du tri, ne peuvent pas être suspendus. Les pauses non prises en charge provoquent des erreurs. Les retours instrumentés ne préservent pas l’optimisation des appels terminaux de Lua.",
		["debugNoEvents"] = "Ajoutez d’abord un événement dans les paramètres du script.",
		["debugPaused"] = "Point d’arrêt atteint",
		["debugProbeBindingsError"] = "Liaison de variable de débogage invalide.",
		["debugProbeBindingsHelp"] = "Pour ce test, le troisième argument facultatif de breakpoint() expose de vraies variables locales : { amount = { get = function() return amount end, set = function(value) amount = value end } }. La console lit via get et affecte via set. Sans set, la variable est en lecture seule. Ces liaisons concernent uniquement le point et l’événement actuels ; les événements en attente gardent leurs propres variables. La capture automatique de portée et l’instrumentation ne sont pas encore implémentées.",
		["debugProbeError"] = "Erreur du test de débogage",
		["debugProbeEvaluate"] = "Évaluer",
		["debugProbeFinished"] = "Exécution terminée",
		["debugProbeHelp"] = "/lwdebug EVENT active le code actuel ; /lwdebug fire ajoute un événement de test ; /lwdebug step avance ; /lwdebug stop annule et vide la file. Utilisez breakpoint(\"nom\", {valeur=valeur}) pour capturer des variables. F10 avance au point suivant lorsque ce panneau ou l’éditeur est actif. Jusqu’à 50 événements attendent dans l’ordre. WoW continue ; les tables restent des références actives. Les pas automatiques par ligne, F11, les imports de modules et les points dans pcall/xpcall ne sont pas pris en charge. Les valeurs secrètes sont masquées dans la liste ; les chaînes secrètes peuvent apparaître directement dans l’infobulle.",
		["debugProbeInput"] = "Expression ou code Lua",
		["debugProbeNotPaused"] = "Arrêtez-vous à un point d’arrêt avant d’évaluer du code.",
		["debugProbeOverflow"] = "%d ignorés",
		["debugProbePaused"] = "Point d’arrêt atteint",
		["debugProbeQueue"] = "En attente : %d",
		["debugProbeReadOnly"] = "Cette variable est en lecture seule.",
		["debugProbeShow"] = "Afficher le code",
		["debugProbeSnapshot"] = "Code capturé (lecture seule)",
		["debugProbeStep"] = "Point suivant (F10)",
		["debugProbeStop"] = "Arrêter le test",
		["debugProbeTerminal"] = "Console de débogage",
		["debugProbeTerminalHelp"] = "La console de test lit les variables transmises à breakpoint() et l’environnement du script. Les liaisons explicites modifient les vraies variables locales ; les autres affectations simples restent dans la console. Les modifications de tables et appels de fonctions affectent le script.\n\nEntrée : évaluer et vider la saisie.\nAlt+Haut/Bas : rappeler jusqu’à 100 commandes.\n/lwdebug eval EXPRESSION évalue aussi du code. Les nouvelles sorties défilent jusqu’en bas ; 100 lignes sont conservées.\n\nLes erreurs maintiennent la pause. Les valeurs secrètes restent masquées.",
		["debugProbeTitle"] = "Test du débogueur",
		["debugProbeVariables"] = "Variables capturées",
		["debugProbeWaiting"] = "En attente d’un événement",
		["debugReadOnly"] = "Protéger le code pendant le débogage",
		["debugScheduleAlways"] = "À chaque connexion/rechargement",
		["debugScheduleCancel"] = "Annuler le débogage programmé",
		["debugScheduleHelp"] = "Programmez un script enregistré dans le menu du débogueur, une fois ou à chaque connexion. ADDON_LOADED concerne LuaWorkbench ; PLAYER_LOGIN la connexion. Le code, les modules et les points d’arrêt enregistrés sont utilisés ; les brouillons sont conservés. L’éditeur démarre réduit sans prendre le focus. L’exécution automatique normale est suspendue tant que le débogueur contrôle ce script, même si la compilation échoue. Arrêter libère le script sans annuler une programmation récurrente. WoW continue de fonctionner ; les addons chargés auparavant ne peuvent pas être débogués rétroactivement.",
		["debugScheduleMenu"] = "Déboguer après connexion/rechargement (code enregistré)",
		["debugScheduleOnce"] = "Une fois",
		["debugShow"] = "Aller à la ligne en pause",
		["debugSnapshot"] = "Code exécuté en débogage",
		["debugSnapshotHelp"] = "Cette vue en lecture seule montre le code utilisé par le débogueur. Les brouillons non enregistrés sont conservés.",
		["debugSourceChanged"] = "Le débogage a été arrêté car le script a changé.",
		["debugStart"] = "Déboguer le script actuel",
		["debugStepInto"] = "Pas à pas détaillé (F11)",
		["debugStepOver"] = "Pas à pas principal (F10)",
		["debugStop"] = "Arrêter le débogage (Shift+F5)",
		["debugTerminal"] = "Console de débogage",
		["debugTerminalHelp"] = "Pendant une pause, évaluez des expressions ou du code Lua. Les affectations modifient les variables locales accessibles ; les modifications de tables et appels de fonctions affectent le script.\n\nEntrée : évaluer et vider la saisie.\nAlt+Haut/Bas : rappeler les commandes précédentes.\nLes nouvelles sorties défilent jusqu’en bas.\n\nLes erreurs maintiennent la pause. Les valeurs secrètes restent masquées dans la console ; les chaînes secrètes peuvent apparaître au survol.",
		["debugTitle"] = "Débogueur",
		["debugUnsupportedYield"] = "Cet appel protégé ou natif ne peut pas être suspendu ; le débogage a été arrêté.",
		["debugVariables"] = "Variables",
		["debugWaitingCallbacks"] = "En attente des événements du script",
		["debugWriteProtected"] = "Lecture seule pendant le débogage",
		["debuggerBudgetExceeded"] = "L’exécution du débogage a été arrêtée après un trop grand nombre d’étapes.",
		["delete"] = "Supprimer",
		["developerToolUnavailable"] = "Impossible de charger cet outil de développement Blizzard.",
		["dirtyText"] = "Texte au lieu du point non enregistré",
		["errorDetails"] = "Détails de l’erreur",
		["errorHistoryHelp"] = "Conserve jusqu’à 100 erreurs récentes de scripts pour cette session, y compris les exécutions automatiques. Les répétitions sont regroupées avec leur nombre et l’heure la plus récente. Un rechargement efface l’historique. Effacer la sortie ne vide pas cette liste.",
		["eventAlreadyAdded"] = "Cet événement figure déjà dans la liste.",
		["eventName"] = "Nom de l’événement…",
		["eventTraceTool"] = "Afficher ou masquer Event Trace (/etrace). Vert : fenêtre ouverte.",
		["findCode"] = "Rechercher dans le code",
		["font"] = "Police",
		["fontChat"] = "Discussion",
		["fontNumbers"] = "Chiffres",
		["fontSize"] = "Taille de police",
		["fontStyle"] = "Style de police",
		["fontUI"] = "Interface",
		["frameStackTool"] = "Activer ou désactiver Frame Stack (/fstack). Vert : actif.",
		["fullscreen"] = "Basculer le plein écran",
		["goToDefinition"] = "Aller à la définition",
		["help"] = "Aide",
		["helpDebug"] = "print(...) écrit dans la sortie. addon et editor désignent LuaWorkbench. Les erreurs restent dans la sortie, le statut est séparé. Copier la sortie sélectionne le texte pour Ctrl+C. Le nombre de lignes est réglable, avec une limite supplémentaire de 64 000 caractères. Le formatage est manuel. Les options règlent les polices, retraits, fermetures de parenthèses, LF/CRLF et le bouton de minicarte. Après un effacement manuel, vous pouvez annuler pendant 10 secondes. La sortie ajoutée ensuite est conservée lors de la restauration ; la limite configurée reste applicable.",
		["helpDump"] = "dump(...) affiche chaque argument séparément dans la sortie, y compris les valeurs nil intermédiaires et finales. dump({...}) affiche une seule table. Exemple : dump(\"valeur\", nil, false). DevTools_Dump(value, startKey) conserve sa signature initiale ; le deuxième argument facultatif nomme la valeur affichée. Cela concerne les exécutions manuelles et automatiques, les modules auxiliaires et le terminal de débogage. Ces fonctions restent propres à l’environnement du script ; les fonctions globales ne changent pas. Les arguments multiples portent les noms arg[1], arg[2], etc. Un argument seul reste sans numéro. Le contenu des tables reste regroupé sous le nom de chaque argument. Utilisez dump(...) pour conserver les arguments nil : une table créée avec {...} ne conserve pas leur nombre total.",
		["helpEditing"] = "Avec le focus dans le code ou la recherche : Ctrl+Entrée exécute, Ctrl+S enregistre, Ctrl+F recherche dans ce code, Ctrl+Maj+F dans tous les noms et codes. F5 exécute si le focus ou le pointeur est dans l’éditeur ; désactivation dans les options. Tab insère des espaces, Maj+Tab réduit le retrait initial. Recherche : Entrée / Maj+Entrée passe au résultat suivant / précédent ; Échap ferme la recherche de code. Renommage : Entrée valide, Échap annule. Un clic droit dans le code modifiable permet de tout formater ou d’insérer un extrait enregistré ou un import de module au curseur actuel. La navigation vers les définitions est réservée à l’éditeur principal. Maj+Alt+F formate l’éditeur de code actif, y compris celui des extraits. Dans l’éditeur principal : Ctrl+Espace ouvre les suggestions, Haut/Bas sélectionne, Entrée / Tab insère et Échap ferme. L’aide souligne le paramètre actuel. Alt+Haut/Bas déplace la ligne ; Alt+Maj+Haut/Bas la duplique. Sans sélection, Ctrl+C/X copie/coupe la ligne et Ctrl+V l’insère au-dessus. Les fins de ligne enregistrées suivent les options. (macOS: ⌘C / ⌘X / ⌘V). Mac : Ctrl+Retour arrière supprime un caractère, Option+Retour arrière le mot précédent et Cmd+Retour arrière jusqu’au début de la ligne. Mac : Option+Gauche/Droite avance par mot ; Cmd+Gauche/Droite va au début/à la fin de la ligne. Ajoutez Maj pour étendre la sélection. Cmd+Haut/Bas va au début/à la fin du code ; ajoutez Maj pour sélectionner.",
		["helpSecretDump"] = "Les dumps secrets dans le chat sont désactivés par défaut. Si cette option est activée, dump() et DevTools_Dump() envoient aussi le dump complet vers la sortie normale de Blizzard lorsque la valeur ou une ligne formatée est secrète. L’éditeur conserve le marqueur vert <secret>. Les dumps ordinaires et print() ne sont pas redirigés. Cela s’applique aussi aux exécutions automatiques ; l’affichage dépend du client et de ses restrictions sur les valeurs secrètes.",
		["helpShortcuts"] = "Raccourcis clavier",
		["helpStorage"] = "Nommez les nouveaux scripts directement dans la liste. Clic droit pour renommer, déplacer, supprimer ou restaurer la version enregistrée. Le point indique des modifications non enregistrées. Ctrl+S remplace la version enregistrée. La récupération des brouillons après rechargement est activée par défaut et désactivable dans les options. Restaurer abandonne les modifications après confirmation. Les flèches replient ou déplient les dossiers.",
		["helpTabDebug"] = "Débogage",
		["helpTabEditor"] = "Éditeur",
		["helpTabScripts"] = "Scripts et modules",
		["helpTabShortcuts"] = "Raccourcis",
		["helperConsumerHelp"] = "Dans un autre script, importez le module sous un nom local. Une fonction locale peut porter le même nom sans remplacer celle du module :",
		["helperCycle"] = "Dépendance circulaire entre modules :",
		["helperDuplicate"] = "Ce nom de module est déjà utilisé :",
		["helperEnabled"] = "Fournir comme module utilitaire",
		["helperHelp"] = "Enregistrez un script et activez-le comme module utilitaire dans ses paramètres, avec un nom unique tel que MyTools. Ce nom est distinct du titre ; la casse ne différencie pas les noms. Le module renvoie une table de fonctions ou de valeurs et ne s’exécute que sur demande de requireHelper. Chaque exécution manuelle ou automatique possède son propre cache ; les imports répétés ou imbriqués partagent la même table. Les modules absents, noms dupliqués, cycles et résultats autres qu’une table produisent une erreur. Les variables restent internes ; écrire dans _G demande une action explicite. Exemple de module :",
		["helperInlineHelp"] = "Un module utilitaire doit se terminer par return tools (ou une autre table). Placez les fonctions à partager dans cette table. requireHelper renvoie cette table pour permettre à un autre script d’appeler ses fonctions. Sans retour de table, l’importation échoue. Seul le code enregistré est exécuté à la demande ; activer cette option ne le lance pas.",
		["helperInvalidName"] = "Commencez par une lettre ou _, puis utilisez lettres, chiffres, _, . ou - (80 caractères maximum).",
		["helperLoadError"] = "Impossible de charger le module utilitaire",
		["helperMissing"] = "Aucun module utilitaire activé et enregistré :",
		["helperModule"] = "Modules utilitaires",
		["helperMustReturnTable"] = "Le module utilitaire doit renvoyer une table :",
		["helperName"] = "Nom de module unique",
		["helperNameHelp"] = "Indépendant du titre du script. Les noms sont uniques sans distinction de casse. Validez les changements avec Entrée.",
		["helperUsageExample"] = "Dans un autre script :",
		["hexColor"] = "Couleur sur six chiffres hexadécimaux (RRGGBB) ; Entrée pour appliquer.",
