		["minimize"] = "Réduire",
		["minimizedOutput"] = "Aperçu des nouvelles sorties en mode réduit",
		["minimizedOutputHelp"] = "L’aperçu facultatif sous la barre réduite affiche un nombre configurable des dernières nouvelles lignes. Sa hauteur s’adapte aux lignes visibles et l’en-tête indique leur nombre. Il disparaît après quelques secondes ; cliquez dessus pour restaurer l’éditeur. Les rafales sont regroupées et la sortie complète reste dans l’éditeur. Désactivé par défaut, avec trois lignes d’aperçu.",
		["minimizedOutputLines"] = "Lignes de l’aperçu réduit",
		["monochrome"] = "Contour monochrome",
		["moveTo"] = "Déplacer vers un dossier…",
		["navigationBack"] = "Retour",
		["navigationHelp"] = "F12 ouvre une déclaration locale ou un export de module identifiable statiquement. Alt+Gauche revient au script, au curseur et au défilement précédents. Les variables locales, paramètres et portées sont pris en compte. La navigation suit les alias locaux explicites de requireHelper avec un nom littéral et des exports de table simples. Les clés dynamiques, définitions générées, métatables et résolutions globales arbitraires ne sont pas déduites. L’analyse reste prudente sur le code volumineux ou incomplet ; ce n’est pas un serveur de langage.",
		["navigationLine"] = "Ligne %d",
		["navigationMissingScript"] = "Le script précédent n’existe plus.",
		["navigationNotFound"] = "Aucune définition statique non ambiguë trouvée ici.",
		["navigationSavedHelp"] = "Ce module contient des modifications non enregistrées. La version utilisée par requireHelper est affichée en lecture seule ; votre brouillon est conservé. Fermez cette vue ou utilisez Alt+Gauche pour revenir.",
