		["outputTop"] = "Ancrer au-dessus",
		["outputWindow"] = "Fenêtre de sortie",
		["outputWindowHelp"] = "Choisissez la disposition dans Options > Sortie ou dans le menu de la fenêtre de sortie. Seul le mode Flottante permet de déplacer la fenêtre par son titre. Une fenêtre ancrée peut uniquement être redimensionnée par le coin inférieur droit. Une fois ancrée, elle suit l’éditeur ; sa position et sa taille sont mémorisées. Choisissez Intégrée pour la replacer dans l’éditeur.",
