		["savedCodeOnly"] = "L’exécution automatique utilise le dernier code enregistré.",
		["scriptSettings"] = "Paramètres du script",
		["scriptSettingsHelp"] = "L’engrenage à côté du nom ouvre les paramètres du script. Le symbole bleu de la liste indique des déclencheurs actifs ; cliquez dessus pour ouvrir les paramètres du script. Le point des modifications non enregistrées est indépendant. L’exécution automatique et l’effacement de la sortie se règlent par script.",
		["searchSnippets"] = "Rechercher scripts et code",
		["secretDumpChat"] = "Dumps secrets dans le chat",
		["sessionErrors"] = "Erreurs de la session",
		["snippetName"] = "Nom de l’script",
		["snippets"] = "Scripts",
		["startupDescription"] = "S’exécute au chargement de LuaWorkbench (ADDON_LOADED), tôt dans le chargement de l’interface.",
		["syntaxColors"] = "Couleurs de syntaxe",
		["syntaxHelp"] = "Choisissez une couleur ou saisissez six chiffres hexadécimaux. L’analyse commune distingue variables locales, paramètres, définitions de fonction et noms non locaux lorsqu’ils sont identifiables statiquement. Les couleurs ne garantissent ni l’existence d’un nom global ni la validité du code. Réinitialiser restaure les couleurs par défaut.",
