		["textSnippetTargetChanged"] = "Le script a changé. Rouvrez la bibliothèque d’extraits pour choisir une position d’insertion.",
		["textSnippets"] = "Extraits de code",
		["textSnippetsHelp"] = "Les extraits sont des fragments de code réutilisables stockés séparément des scripts exécutables. Ouvrez Extraits de code pour choisir, créer, rechercher, modifier, enregistrer ou supprimer un extrait. Insérer ajoute le fragment à la position du curseur mémorisée à l’ouverture de la bibliothèque, sans exécuter de code. Pour enregistrer du code existant, copiez-le puis collez-le dans l’éditeur de la bibliothèque. La recherche porte sur les noms et le code enregistré.",
