		["apiFunction"] = "Funzione API Blizzard",
		["apiFunctions"] = "Funzioni / metodi",
		["apiHelp"] = "Guida ed evidenziazione API Blizzard",
		["apiIndexing"] = "Preparazione ricerca nel testo: %d / %d · ricerca per nome disponibile",
		["apiOptional"] = "facoltativo",
		["apiOther"] = "Altro",
		["apiPayload"] = "Argomenti evento",
