		["apiTypes"] = "Tipi",
		["apiUnavailable"] = "Impossibile caricare la documentazione API Blizzard. Riapri l’editor per riprovare.",
		["autoIndent"] = "Rientro automatico",
		["autoPairs"] = "Chiudi parentesi e virgolette",
		["autoRunHelp"] = "L’esecuzione automatica usa il codice salvato, mai le modifiche non salvate. L’avvio avviene una volta al caricamento di LuaWorkbench (ADDON_LOADED); l’accesso una volta a PLAYER_LOGIN, anche dopo un ricaricamento. Se entrambi sono attivi, lo script parte in entrambe le fasi. Gli eventi personalizzati lo avviano a ogni occorrenza, anche con l’editor chiuso. Tutte le opzioni sono disattivate inizialmente; attivarle non avvia subito il codice.",
		["autocomplete"] = "Completamento codice e suggerimenti parametri",
		["autocompleteHelp"] = "Enter / Tab: inserisci · Esc: chiudi · Ctrl+Spazio: suggerimenti",
		["automaticRun"] = "Esecuzione automatica",
