		["minimapToggle"] = "Mostra / nascondi pulsante minimappa",
		["minimize"] = "Riduci a icona",
		["minimizedOutput"] = "Anteprima output quando ridotto",
		["minimizedOutputHelp"] = "L’anteprima opzionale sotto la barra ridotta mostra un numero configurabile delle ultime nuove righe. L’altezza si adatta alle righe visibili e l’intestazione ne indica il numero. Svanisce dopo pochi secondi; fai clic per ripristinare l’editor. Le raffiche sono raggruppate e l’output completo rimane nell’editor. Disattivata per impostazione predefinita, con tre righe di anteprima.",
		["minimizedOutputLines"] = "Righe dell’anteprima ridotta",
		["monochrome"] = "Contorno monocromatico",
		["moveTo"] = "Sposta nella cartella…",
		["navigationBack"] = "Indietro",
		["navigationHelp"] = "F12 apre una dichiarazione locale o un’esportazione del modulo riconoscibile staticamente. Alt+Sinistra torna allo script, cursore e scorrimento precedenti. Sono considerate variabili locali, parametri e ambiti. La navigazione segue alias locali espliciti di requireHelper con nomi letterali ed esportazioni semplici di tabelle. Non deduce chiavi dinamiche, definizioni generate, metatabelle o risoluzioni globali arbitrarie. Il codice grande o incompleto viene analizzato con prudenza; non è un server di linguaggio.",
		["navigationLine"] = "Riga %d",
		["navigationMissingScript"] = "Lo script precedente non esiste più.",
		["navigationNotFound"] = "Nessuna definizione statica univoca trovata qui.",
		["navigationSavedHelp"] = "Questo modulo ha modifiche non salvate. La versione salvata usata da requireHelper viene mostrata in sola lettura; la bozza è conservata. Chiudi questa vista o usa Alt+Sinistra per tornare.",
