		["outputWindow"] = "Finestra di output",
		["outputWindowHelp"] = "Scegli la disposizione in Opzioni > Output o nel menu della finestra di output. Solo la modalità Mobile permette di trascinare la finestra dalla barra del titolo. Le finestre ancorate possono solo essere ridimensionate dall’angolo inferiore destro. Quando è ancorata segue l’editor; posizione e dimensioni vengono salvate. Scegli Integrata per riportarla nell’editor.",
