		["textSnippetTargetChanged"] = "Lo script è cambiato. Riapri la libreria dei frammenti per scegliere la posizione di inserimento.",
		["textSnippets"] = "Frammenti di codice",
		["textSnippetsHelp"] = "I frammenti sono codice riutilizzabile archiviato separatamente dagli script eseguibili. Apri Frammenti di codice per scegliere, creare, cercare, modificare, salvare o eliminare un frammento. Inserisci aggiunge il frammento alla posizione del cursore memorizzata all’apertura della libreria, senza eseguire codice. Per salvare codice esistente, copialo e incollalo nell’editor della libreria. La ricerca include nomi e codice salvato.",
