		["apiUnavailable"] = "블리자드 API 문서를 불러오지 못했습니다. 편집기를 다시 열어 재시도하세요.",
		["autoIndent"] = "자동 들여쓰기",
		["autoPairs"] = "괄호 및 따옴표 자동 닫기",
		["autoRunHelp"] = "자동 실행은 저장된 코드만 사용하며 저장하지 않은 변경 사항은 실행하지 않습니다. 시작 실행은 LuaWorkbench 로드 시(ADDON_LOADED) 한 번, 로그인 실행은 PLAYER_LOGIN 시 한 번 실행되며 UI 재시작도 포함됩니다. 둘 다 켜면 두 단계에서 실행됩니다. 사용자 지정 이벤트는 편집기가 닫혀 있어도 발생할 때마다 실행합니다. 기본값은 모두 꺼짐이며 옵션을 켜도 즉시 실행하지 않습니다.",
		["autocomplete"] = "코드 자동 완성 및 매개변수 도움말",
		["autocompleteHelp"] = "Enter / Tab: 삽입 · Esc: 닫기 · Ctrl+Space: 제안",
