		["colorPunctuation"] = "괄호 및 문장 부호",
		["colorString"] = "문자열",
		["confirmDelete"] = "이 스크립트을 삭제하시겠습니까?",
		["confirmRevert"] = "저장되지 않은 변경 사항을 버리고 마지막 저장 버전을 복원하시겠습니까?",
		["copyOutputAction"] = "복사",
		["copyOutputHint"] = "텍스트를 선택한 후 Ctrl+C로 복사하세요.",
		["cursorPosition"] = "행 %d, 열 %d",
		["customEventHelp"] = "WoW 이벤트 이름을 입력하고 Enter 또는 +로 추가하세요. 이벤트를 개별적으로 켜거나 제거할 수 있으며 잘못된 이벤트는 거부됩니다. 스크립트에서 event는 이름, ...는 인수입니다. 시작 실행은 ADDON_LOADED 인수를 전달합니다. 자동 실행 전에 스크립트를 저장하세요.",
		["customEvents"] = "사용자 지정 이벤트",
		["customize"] = "사용자 지정…",
		["debugBreakpoint"] = "중단점 전환 (F9)",
		["debugCallbackHelp"] = "코드에 정의한 OnEvent 처리기를 디버깅하려면 :SetScript(\"OnEvent\", ...) 또는 :HookScript(\"OnEvent\", ...)를 사용하고 콜백 안에 중단점을 설정한 뒤 현재 스크립트 디버깅을 한 번 시작하세요. 등록 후 발생한 이벤트는 디버거에서 콜백을 실행합니다. CreateFrame과 _G.CreateFrame 모두 사용할 수 있습니다. 일시 정지 중 최대 50개 이벤트가 대기하며 가득 차면 새 이벤트는 버려집니다. nil 인수는 유지됩니다. 중지 시 디버그 처리기가 아직 설치되어 있으면 이전 SetScript 처리기를 복원합니다. HookScript 훅은 제거할 수 없으므로 중지하면 비활성화됩니다.",
		["debugClearBreakpoints"] = "중단점 모두 지우기",
		["debugContinue"] = "계속 (F5)",
		["debugDrawer"] = "디버그 콘솔 표시 또는 숨기기",
		["debugEvents"] = "설정한 이벤트 디버깅",
		["debugEventsHelp"] = "이벤트 디버깅은 활성화된 사용자 지정 이벤트와 설정된 경우 PLAYER_LOGIN을 기다립니다. 시작이나 로그인을 다시 실행하지 않습니다. 코드를 즉시 시험하려면 현재 스크립트 디버깅을 사용하세요.",
		["debugHelp"] = "줄 번호를 클릭하면 중단점을 설정하거나 해제합니다. 실행 옆의 디버거 버튼으로 시작하거나 설정한 이벤트를 선택하세요. F5는 계속, F10은 함수 내부로 들어가지 않고 실행, F11은 스크립트 함수 내부로 진입, Shift+F5는 중지합니다. 콘솔에서 정지한 줄의 지역 변수를 읽고 변경할 수 있습니다. 편집기에서 변수 위에 마우스를 올려 값을 확인하세요. WoW는 계속 실행되며 새 이벤트는 크기가 제한된 대기열에서 기다립니다. 중단점은 스크립트별로 저장되어 UI 재시작 후에도 유지되며 텍스트를 추가하거나 삭제하면 해당 줄을 따라 이동합니다. 실행할 수 없는 줄의 표시는 유지되지만 일시 정지하지 않습니다. 코드 줄 전체를 삭제하면 해당 중단점이 제거될 수 있습니다.",
		["debugHelperHelp"] = "F10은 도우미 호출을 건너뛰고 F11은 requireHelper로 불러온 저장된 도우미 모듈 안으로 들어갑니다. 편집기와 실행한 코드가 같으면 일반 편집기를 사용합니다. 저장하지 않은 초안이 다르면 읽기 전용 복사본을 열고 초안은 유지합니다. 새 디버그 세션 전에 도우미 변경 사항을 저장하세요.",
		["debugInspectUnavailable"] = "현재 범위에 값이 없습니다",
		["debugLimits"] = "디버거는 코드 복사본을 사용합니다. 활성 스크립트를 편집하면 디버깅이 중지되지만 중단점은 유지되며 변경된 줄에 맞춰 조정됩니다. :SetScript 또는 :HookScript로 등록한 OnEvent 콜백만 대기열에 추가됩니다. 직접 pcall/xpcall 호출은 단계 실행 없이 수행됩니다. 네이티브 함수 안으로는 들어갈 수 없으며 정렬 콜백처럼 네이티브 함수에 동기적으로 반환해야 하는 콜백은 일시 정지할 수 없습니다. 지원되지 않는 일시 정지는 오류를 발생시킵니다. 계측한 반환문은 Lua의 꼬리 호출 최적화를 유지하지 않습니다.",
		["debugNoEvents"] = "먼저 스크립트 설정에서 이벤트를 추가하세요.",
		["debugPaused"] = "중단점 도달",
		["debugProbeBindingsError"] = "잘못된 디버거 변수 바인딩입니다.",
		["debugProbeBindingsHelp"] = "이 테스트에서 breakpoint()의 선택적 세 번째 인수는 실제 지역 변수를 노출합니다: { amount = { get = function() return amount end, set = function(value) amount = value end } }. 콘솔은 get으로 읽고 set으로 대입합니다. set이 없으면 읽기 전용입니다. 바인딩은 현재 중단점과 이벤트 호출에만 적용되며 대기 중인 이벤트는 자체 변수를 유지합니다. 자동 범위 캡처와 코드 계측은 아직 구현되지 않았습니다.",
		["debugProbeError"] = "디버거 테스트 오류",
		["debugProbeEvaluate"] = "평가",
		["debugProbeFinished"] = "실행 완료",
		["debugProbeHelp"] = "/lwdebug EVENT로 현재 코드를 활성화하고 /lwdebug fire로 테스트 이벤트를 추가합니다. /lwdebug step은 진행하고 /lwdebug stop은 중지하며 대기열을 비웁니다. breakpoint(\"이름\", {value=value})로 변수를 캡처하세요. 이 패널이나 편집기가 활성화된 동안 F10으로 다음 중단점으로 이동합니다. 최대 50개 이벤트가 순서대로 대기합니다. WoW는 계속 실행되며 테이블은 실시간 참조입니다. 자동 줄 단위 진행, F11, 모듈 가져오기 및 pcall/xpcall 내부 중단점은 지원하지 않습니다. 비밀 값은 목록에서 숨기며 비밀 문자열은 툴팁에 직접 표시될 수 있습니다.",
		["debugProbeInput"] = "표현식 또는 Lua 코드",
		["debugProbeNotPaused"] = "코드를 평가하기 전에 중단점에서 멈추세요.",
		["debugProbeOverflow"] = "%d개 제외됨",
		["debugProbePaused"] = "중단점 도달",
		["debugProbeQueue"] = "대기: %d",
		["debugProbeReadOnly"] = "읽기 전용 변수입니다.",
		["debugProbeShow"] = "코드 보기",
		["debugProbeSnapshot"] = "캡처한 코드 (읽기 전용)",
		["debugProbeStep"] = "다음 중단점 (F10)",
		["debugProbeStop"] = "테스트 중지",
		["debugProbeTerminal"] = "디버그 콘솔",
		["debugProbeTerminalHelp"] = "테스트 콘솔은 breakpoint()에 전달한 변수와 스크립트 환경을 읽습니다. 명시적 바인딩은 실제 지역 변수를 변경하며 다른 단순 대입은 콘솔에만 적용됩니다. 테이블 변경과 함수 호출은 스크립트에 영향을 줍니다.\n\nEnter: 평가 후 입력란 비우기.\nAlt+위/아래: 이전 명령 최대 100개 불러오기.\n/lwdebug eval 표현식으로도 평가할 수 있습니다. 새 출력은 맨 아래로 스크롤되며 100줄을 보관합니다.\n\n오류가 나도 일시 정지는 유지됩니다. 비밀 값은 숨겨집니다.",
		["debugProbeTitle"] = "디버거 테스트",
		["debugProbeVariables"] = "캡처한 변수",
		["debugProbeWaiting"] = "이벤트 대기 중",
		["debugReadOnly"] = "디버깅 중 코드 쓰기 보호",
		["debugScheduleAlways"] = "로그인/재시작마다",
		["debugScheduleCancel"] = "예약된 디버깅 취소",
		["debugScheduleHelp"] = "디버거 메뉴에서 저장된 스크립트 하나를 다음 로그인/재시작에 한 번 또는 매번 실행하도록 예약합니다. ADDON_LOADED는 LuaWorkbench 로드, PLAYER_LOGIN은 로그인을 뜻합니다. 저장된 코드, 도우미, 중단점을 사용하며 초안은 유지됩니다. 편집기는 포커스를 가져오지 않고 최소화 상태로 시작합니다. 디버거가 스크립트를 관리하는 동안 컴파일 실패 시에도 일반 자동 실행을 막습니다. 중지는 실행 제어를 해제하지만 반복 예약은 취소하지 않습니다. WoW는 계속 실행되며 먼저 로드된 애드온은 소급하여 디버깅할 수 없습니다.",
		["debugScheduleMenu"] = "로그인/재시작 후 디버깅 (저장된 코드)",
		["debugScheduleOnce"] = "한 번",
		["debugShow"] = "일시 정지한 줄로 이동",
		["debugSnapshot"] = "디버거에서 실행한 코드",
		["debugSnapshotHelp"] = "이 읽기 전용 보기에는 디버거가 사용한 코드가 표시됩니다. 편집기의 저장하지 않은 초안은 유지됩니다.",
		["debugSourceChanged"] = "스크립트가 변경되어 디버깅을 중지했습니다.",
		["debugStart"] = "현재 스크립트 디버깅",
		["debugStepInto"] = "한 단계씩 코드 실행 (F11)",
		["debugStepOver"] = "프로시저 단위 실행 (F10)",
		["debugStop"] = "디버깅 중지 (Shift+F5)",
		["debugTerminal"] = "디버그 콘솔",
		["debugTerminalHelp"] = "일시 정지 중에 표현식이나 Lua 코드를 평가합니다. 대입은 접근 가능한 지역 변수를 바꾸며 테이블 변경과 함수 호출은 실행 중인 스크립트에 영향을 줍니다.\n\nEnter: 평가 후 입력란 비우기.\nAlt+위/아래: 이전 명령 불러오기.\n새 출력은 맨 아래로 스크롤됩니다.\n\n오류가 나도 일시 정지는 유지됩니다. 비밀 값은 콘솔에서 숨겨지지만 비밀 문자열은 마우스 툴팁에 표시될 수 있습니다.",
		["debugTitle"] = "디버거",
		["debugUnsupportedYield"] = "이 보호된 호출 또는 네이티브 호출은 일시 정지할 수 없어 디버깅을 중지했습니다.",
		["debugVariables"] = "변수",
		["debugWaitingCallbacks"] = "스크립트 이벤트 대기 중",
		["debugWriteProtected"] = "디버깅 중 읽기 전용",
		["debuggerBudgetExceeded"] = "실행 단계가 너무 많아 디버깅을 중지했습니다.",
		["delete"] = "삭제",
		["developerToolUnavailable"] = "이 블리자드 개발자 도구를 불러올 수 없습니다.",
		["dirtyText"] = "미저장 점 대신 텍스트",
		["errorDetails"] = "오류 상세 정보",
		["errorHistoryHelp"] = "자동 실행을 포함하여 이번 세션의 최근 스크립트 오류를 최대 100개 보관합니다. 같은 오류는 횟수와 마지막 시각으로 묶습니다. UI를 재시작하면 기록이 지워집니다. 출력 지우기는 이 목록을 지우지 않습니다.",
		["eventAlreadyAdded"] = "이미 목록에 있는 이벤트입니다.",
		["eventName"] = "이벤트 이름 입력…",
		["eventTraceTool"] = "Event Trace 표시 또는 숨기기 (/etrace). 녹색: 창 열림.",
		["findCode"] = "코드에서 찾기",
		["font"] = "글꼴",
		["fontChat"] = "대화",
		["fontNumbers"] = "숫자",
		["fontSize"] = "글꼴 크기",
		["fontStyle"] = "글꼴 스타일",
		["fontUI"] = "인터페이스",
		["frameStackTool"] = "Frame Stack 전환 (/fstack). 녹색: 활성화.",
		["fullscreen"] = "전체 화면 전환",
		["goToDefinition"] = "정의로 이동",
		["help"] = "도움말",
		["helpDebug"] = "print(...)는 출력에 기록합니다. addon과 editor는 LuaWorkbench를 가리킵니다. 오류는 출력에 남고 실행 상태는 따로 표시됩니다. 출력 복사는 Ctrl+C를 위해 텍스트를 선택합니다. 출력 줄 수는 설정할 수 있으며 64,000자 제한도 적용됩니다. 코드 서식은 직접 요청할 때만 변경됩니다. 옵션에서 글꼴, 들여쓰기, 괄호, LF/CRLF 및 미니맵 버튼을 설정합니다. 출력을 수동으로 지운 후 10초 동안 실행 취소할 수 있습니다. 복원할 때 이후 추가된 출력도 유지되며 설정한 출력 제한은 계속 적용됩니다.",
		["helpDump"] = "dump(...)는 각 인수를 출력에 따로 표시하며 인수 사이와 끝의 nil 값도 유지합니다. dump({...})는 대신 하나의 테이블을 출력합니다. 예: dump(\"값\", nil, false). DevTools_Dump(value, startKey)는 기존 호출 형식을 유지하며 선택적인 두 번째 인수는 출력할 값의 이름입니다. 수동 실행, 자동 실행, 헬퍼 모듈과 디버그 터미널에 모두 적용됩니다. 이 함수들은 스크립트 환경에서만 사용되며 전역 함수는 변경되지 않습니다. 인수가 여러 개이면 arg[1], arg[2] 등으로 표시하며 하나이면 번호를 붙이지 않습니다. 테이블 내용은 해당 인수 이름 아래에 표시됩니다. nil 인수를 유지하려면 dump(...)를 사용하세요. {...}로 만든 테이블은 전체 인수 개수를 보존하지 않습니다.",
		["helpEditing"] = "코드 또는 검색 필드에 포커스가 있을 때: Ctrl+Enter 실행, Ctrl+S 저장, Ctrl+F 현재 코드 검색, Ctrl+Shift+F 모든 스크립트 이름과 코드 검색. 편집기에 포커스나 마우스 포인터가 있으면 F5로 실행하며 옵션에서 끌 수 있습니다. Tab은 공백 삽입, Shift+Tab은 앞쪽 들여쓰기 제거입니다. 검색에서 Enter / Shift+Enter는 다음 / 이전 결과, Escape는 코드 검색 닫기입니다. 이름 변경 시 Enter는 확인, Escape는 취소입니다. 편집 가능한 코드를 오른쪽 클릭하면 전체 코드를 정렬하거나 현재 커서에 저장된 코드 조각 또는 모듈 가져오기를 삽입할 수 있습니다. 정의 탐색은 기본 편집기에서만 사용할 수 있습니다. Shift+Alt+F는 코드 조각 편집기를 포함해 포커스가 있는 코드 편집기를 정렬합니다. 주 편집기: Ctrl+Space로 제안을 열고 위/아래로 선택하며 Enter / Tab으로 삽입하고 Esc로 닫습니다. 매개변수 도움말은 현재 인수를 표시합니다. Alt+위/아래는 줄 이동, Alt+Shift+위/아래는 줄 복제입니다. 선택 영역이 없으면 Ctrl+C/X는 줄 복사/잘라내기, Ctrl+V는 현재 줄 위에 삽입합니다. 저장 줄바꿈은 옵션을 따릅니다. (macOS: ⌘C / ⌘X / ⌘V). Mac: Ctrl+Backspace는 한 글자, Option+Backspace는 이전 단어, Cmd+Backspace는 줄 시작까지 삭제합니다. Mac: Option+왼쪽/오른쪽은 단어 단위, Cmd+왼쪽/오른쪽은 줄 시작/끝으로 이동합니다. Shift를 함께 누르면 선택 영역을 확장합니다. Cmd+위/아래는 코드 시작/끝으로 이동하며 Shift를 함께 누르면 선택합니다.",
		["helpSecretDump"] = "기본적으로 꺼져 있습니다. 켜면 값이나 서식이 적용된 줄이 비밀 값일 때 dump()와 DevTools_Dump()가 전체 덤프를 블리자드의 기본 출력으로도 보냅니다. 편집기에는 녹색 <secret> 표시가 유지됩니다. 일반 덤프와 print()는 전달하지 않습니다. 자동 실행에도 적용되며 실제 표시 범위는 클라이언트와 비밀 값 제한에 따라 달라집니다.",
		["helpShortcuts"] = "단축키",
		["helpStorage"] = "새 스크립트 이름은 목록에서 바로 입력합니다. 우클릭으로 이름 변경, 이동, 삭제, 저장된 버전 복원을 할 수 있습니다. 점은 저장되지 않은 변경을 나타냅니다. Ctrl+S는 저장된 버전을 대체합니다. 재접속 시 초안 복원은 기본으로 켜져 있으며 옵션에서 끌 수 있습니다. 저장된 버전 복원은 확인 후 변경을 버립니다. 폴더 화살표로 접거나 펼칩니다.",
		["helpTabDebug"] = "디버깅",
		["helpTabEditor"] = "편집기",
		["helpTabScripts"] = "스크립트와 모듈",
		["helpTabShortcuts"] = "단축키",
		["helperConsumerHelp"] = "다른 스크립트에서 도우미를 지역 이름으로 가져오세요. 같은 이름의 지역 함수를 만들어도 도우미의 함수는 바뀌지 않습니다:",
		["helperCycle"] = "도우미 모듈 순환 의존성:",
		["helperDuplicate"] = "이미 사용 중인 모듈 이름:",
		["helperEnabled"] = "도우미 모듈로 제공",
		["helperHelp"] = "스크립트를 저장한 후 설정에서 MyTools와 같은 고유 이름으로 도우미 모듈을 활성화하세요. 모듈 이름은 표시 제목과 별개이며 대소문자만 다른 이름도 중복입니다. 도우미는 함수나 값이 담긴 테이블을 반환하고 requireHelper가 요청할 때만 실행됩니다. 각 수동 또는 자동 실행은 새 캐시를 사용하며 같은 실행 안의 반복 및 중첩 가져오기는 같은 테이블을 공유합니다. 모듈 누락, 이름 중복, 순환 의존성, 테이블이 아닌 반환값은 오류를 발생시킵니다. 변수는 내부 환경에 남으며 _G에 쓰려면 명시적으로 지정해야 합니다. 도우미 예제:",
		["helperInlineHelp"] = "헬퍼는 마지막에 return tools로 테이블을 반환해야 합니다(다른 테이블도 가능). 공유할 함수를 그 테이블에 넣으세요. requireHelper는 이 테이블을 반환하므로 다른 스크립트에서 그 함수를 호출할 수 있습니다. 테이블을 반환하지 않으면 가져오기에 실패합니다. 요청할 때 저장된 코드만 실행되며, 이 옵션을 켜는 것만으로 실행되지는 않습니다.",
		["helperInvalidName"] = "영문자 또는 _로 시작하고 영문자, 숫자, _, ., -를 사용하세요(최대 80자).",
		["helperLoadError"] = "도우미 모듈을 불러올 수 없습니다",
		["helperMissing"] = "활성화된 저장 도우미 모듈이 없습니다:",
		["helperModule"] = "도우미 모듈",
		["helperMustReturnTable"] = "도우미 모듈은 테이블을 반환해야 합니다:",
		["helperName"] = "고유 모듈 이름",
		["helperNameHelp"] = "스크립트 제목과 별개입니다. 모듈 이름은 대소문자 구분 없이 고유해야 합니다. 변경한 이름은 Enter로 적용합니다.",
		["helperUsageExample"] = "다른 스크립트에서:",
		["hexColor"] = "16진수 6자리 색상(RRGGBB)을 입력하고 Enter로 적용하세요.",
		["indentWidth"] = "들여쓰기 너비 (공백)",
