		["knowledgeBase"] = "지식 베이스",
		["lineEnding"] = "저장된 줄 바꿈",
		["loginDescription"] = "UI 재시작 후를 포함하여 PLAYER_LOGIN에 실행합니다.",
		["manualRun"] = "수동",
		["matchCase"] = "대소문자 구분",
		["matchPosition"] = "%d / %d",
		["matches"] = "결과 %d개",
		["maximizeCode"] = "코드 영역 최대화 / 복원",
		["minimapHint"] = "Lua 편집기 열기 또는 복원",
		["minimapToggle"] = "미니맵 버튼 표시 / 숨기기",
		["minimize"] = "최소화",
		["minimizedOutput"] = "최소화 상태에서 새 출력 미리 보기",
		["minimizedOutputHelp"] = "최소화 막대 아래의 선택적 미리 보기는 설정한 수만큼 최신 새 줄을 표시합니다. 높이는 표시된 줄에 맞춰 조정되며 머리글에 표시된 줄 수가 나옵니다. 몇 초 후 사라지고 클릭하면 편집기를 엽니다. 연속 출력은 묶어서 표시하며 전체 출력은 편집기에 남습니다. 기본적으로 꺼져 있고 미리 보기 줄 수는 3줄입니다.",
		["minimizedOutputLines"] = "최소화 미리 보기 줄 수",
		["monochrome"] = "단색 외곽선",
		["moveTo"] = "폴더로 이동…",
		["navigationBack"] = "뒤로",
		["navigationHelp"] = "F12로 지역 선언이나 정적으로 확인 가능한 도우미 내보내기로 이동합니다. Alt+왼쪽 화살표는 이전 스크립트, 커서 및 스크롤 위치로 돌아갑니다. 지역 변수, 매개변수, 이름의 범위를 고려합니다. 문자열 이름을 사용하는 명시적인 requireHelper 지역 별칭과 단순한 테이블 내보내기를 지원합니다. 동적 키, 실행 중 생성된 정의, 메타테이블, 임의의 전역 참조는 추론하지 않습니다. 크거나 미완성인 코드는 보수적으로 분석하며 언어 서버가 아닙니다.",
		["navigationLine"] = "%d행",
		["navigationMissingScript"] = "이전 스크립트가 더 이상 없습니다.",
		["navigationNotFound"] = "명확한 정적 정의를 찾지 못했습니다.",
		["navigationSavedHelp"] = "이 도우미에는 저장하지 않은 변경 사항이 있습니다. requireHelper가 사용하는 저장된 버전을 읽기 전용으로 표시하며 초안은 보존합니다. 이 창을 닫거나 Alt+왼쪽 화살표로 돌아가세요.",
		["navigationSavedVersion"] = "저장된 버전(읽기 전용)",
