		["outputAutoScroll"] = "자동 스크롤",
		["outputAutoScrollHelp"] = "새 출력이 추가되면 자동으로 끝으로 이동합니다. 끄면 현재 스크롤 위치를 유지합니다.",
		["outputBottom"] = "아래에 고정",
