		["outputLeft"] = "왼쪽에 고정",
		["outputLimit"] = "보관할 출력 줄 수",
		["outputRight"] = "오른쪽에 고정",
		["outputTop"] = "위에 고정",
		["outputWindow"] = "출력 창",
		["outputWindowHelp"] = "설정 > 출력 또는 출력 창 메뉴에서 배치를 선택하세요. 자유 이동 모드에서만 제목 표시줄을 끌어 이동할 수 있습니다. 고정된 창은 오른쪽 아래 모서리에서 크기만 조절할 수 있습니다. 고정된 창은 편집기를 따라 움직이며 위치와 크기가 저장됩니다. 통합을 선택하면 편집기로 돌아갑니다.",
