		["scriptSettings"] = "스크립트 설정",
		["scriptSettingsHelp"] = "스크립트 이름 옆 톱니바퀴로 설정을 엽니다. 목록의 파란 자동 실행 아이콘은 활성 트리거를 나타내며 클릭하면 해당 스크립트의 설정을 엽니다. 저장하지 않은 변경 점은 별개입니다. 자동 실행과 실행 전 출력 지우기는 스크립트별 설정입니다.",
