		["startupDescription"] = "UI 로딩 초기에 LuaWorkbench가 로드될 때(ADDON_LOADED) 실행합니다.",
		["syntaxColors"] = "구문 색상",
		["syntaxHelp"] = "색상을 선택하거나 6자리 16진수 값을 입력하세요. 공통 코드 분석은 정적으로 확인할 수 있는 지역 변수, 매개변수, 함수 정의, 비지역 이름을 구분합니다. 색상은 전역 이름이 실제로 존재하거나 코드가 올바름을 뜻하지 않습니다. 초기화하면 기본 색상으로 돌아갑니다.",
		["tableInspectTool"] = "테이블 검사기 열기 (/tableinspect, /tinspect).",
		["textSnippetCode"] = "코드 조각",
		["textSnippetDelete"] = "코드 조각 삭제",
		["textSnippetDeleteConfirm"] = "이 코드 조각을 삭제할까요?",
		["textSnippetEmpty"] = "코드 조각을 찾지 못했습니다.",
		["textSnippetInsert"] = "코드 조각 삽입",
		["textSnippetName"] = "이름",
		["textSnippetNew"] = "새 코드 조각",
		["textSnippetRequired"] = "이름과 코드 조각을 입력하세요.",
		["textSnippetSave"] = "코드 조각 저장",
		["textSnippetSearch"] = "이름 및 코드 검색",
		["textSnippetTargetChanged"] = "스크립트가 변경되었습니다. 코드 조각 라이브러리를 다시 열어 삽입 위치를 지정하세요.",
		["textSnippets"] = "코드 조각",
		["textSnippetsHelp"] = "코드 조각은 실행 가능한 스크립트와 별도로 저장하는 재사용 코드입니다. 코드 조각을 열어 선택, 생성, 검색, 편집, 저장 또는 삭제할 수 있습니다. 삽입은 라이브러리를 열 때 기록한 커서 위치에 조각을 추가하며 코드를 실행하지 않습니다. 기존 코드를 조각으로 저장하려면 복사하여 라이브러리 편집기에 붙여넣으세요. 이름과 저장된 코드를 모두 검색합니다.",
		["thickOutline"] = "두꺼운 외곽선",
