		["apiFunction"] = "Função da API da Blizzard",
		["apiFunctions"] = "Funções / métodos",
		["apiHelp"] = "Ajuda e destaque da API da Blizzard",
		["apiIndexing"] = "Preparando pesquisa de texto: %d / %d · pesquisa por nome disponível",
		["apiOptional"] = "opcional",
