		["apiTypes"] = "Tipos",
		["apiUnavailable"] = "Não foi possível carregar a documentação da API da Blizzard. Reabra o editor para tentar novamente.",
		["autoIndent"] = "Recuo automático",
		["autoPairs"] = "Fechar parênteses e aspas",
		["autoRunHelp"] = "A execução automática usa o código salvo, nunca alterações não salvas. A inicialização ocorre uma vez ao carregar LuaWorkbench (ADDON_LOADED); a entrada, uma vez em PLAYER_LOGIN, inclusive após recarregar. Se ambos estiverem ativos, o script executa nas duas etapas. Eventos personalizados executam a cada ocorrência, mesmo com o editor fechado. Tudo vem desativado; ativar uma opção não executa o código imediatamente.",
		["autocomplete"] = "Conclusão de código e ajuda de parâmetros",
		["autocompleteHelp"] = "Enter / Tab: inserir · Esc: fechar · Ctrl+Espaço: sugestões",
		["automaticRun"] = "Execução automática",
		["clearErrors"] = "Limpar erros",
		["clearOnRun"] = "Limpar saída ao executar",
		["clearOutputAction"] = "Limpar",
		["clearSearch"] = "Limpar pesquisa",
		["colorCall"] = "Chamadas de função",
		["colorComment"] = "Comentários",
		["colorFunctionName"] = "Definições de função",
		["colorGlobalVariable"] = "Nomes não locais",
		["colorIdentifier"] = "Nomes / identificadores",
		["colorKeyword"] = "Palavras-chave",
		["colorLiteral"] = "true / false / nil",
		["colorLocalVariable"] = "Variáveis locais",
		["colorNumber"] = "Números",
		["colorOperator"] = "Operadores",
		["colorParameter"] = "Parâmetros de função",
		["colorPunctuation"] = "Parênteses e pontuação",
		["colorString"] = "Textos",
		["confirmDelete"] = "Excluir este script?",
		["confirmRevert"] = "Descartar alterações não salvas e restaurar a última versão salva?",
		["copyOutputAction"] = "Copiar",
		["copyOutputHint"] = "Selecione o texto e pressione Ctrl+C para copiar.",
		["cursorPosition"] = "Lin %d, Col %d",
		["customEventHelp"] = "Digite um evento do WoW e pressione Enter ou + para adicionar. Cada evento pode ser ativado ou removido separadamente. Eventos inválidos são rejeitados. No script, event contém o nome e ... os argumentos. A inicialização passa os argumentos de ADDON_LOADED. Salve o script antes da execução automática.",
		["customEvents"] = "Eventos personalizados",
		["customize"] = "Personalizar…",
		["debugBreakpoint"] = "Alternar ponto de interrupção (F9)",
		["debugCallbackHelp"] = "Para depurar um manipulador OnEvent definido no código, use :SetScript(\"OnEvent\", ...) ou :HookScript(\"OnEvent\", ...), coloque um ponto de interrupção no callback e inicie Depurar script atual uma vez. Após o registro, eventos recebidos executam o callback no depurador. CreateFrame e _G.CreateFrame funcionam. Até 50 eventos aguardam durante a pausa; novos eventos são descartados se a fila estiver cheia, e argumentos nil são preservados. Ao parar, o manipulador SetScript anterior é restaurado se o de depuração ainda estiver instalado. Hooks HookScript não podem ser removidos e ficam inativos ao parar.",
		["debugClearBreakpoints"] = "Limpar pontos de interrupção",
		["debugContinue"] = "Continuar (F5)",
		["debugDrawer"] = "Mostrar ou ocultar console de depuração",
		["debugEvents"] = "Depurar eventos configurados",
		["debugEventsHelp"] = "A depuração de eventos aguarda eventos personalizados ativados e PLAYER_LOGIN, se configurado. Não repete inicialização nem login. Use Depurar script atual para testar o código imediatamente.",
		["debugHelp"] = "Clique em um número de linha para alternar um ponto de interrupção. Inicie pelo botão de depuração ao lado de Executar ou escolha os eventos configurados. F5 continua, F10 avança sem entrar, F11 entra nas funções do script e Shift+F5 para. O console pode ler e alterar variáveis locais na linha pausada. Passe o cursor sobre uma variável para inspecioná-la. Novos eventos aguardam em uma fila limitada enquanto WoW continua. Os pontos de interrupção são salvos por script entre recargas e acompanham suas linhas ao inserir ou remover texto. Marcadores em linhas não executáveis permanecem, mas não pausam; apagar uma linha inteira pode remover seu ponto.",
		["debugHelperHelp"] = "F10 passa pelas chamadas de módulos; F11 entra em módulos salvos carregados por requireHelper. Se o editor corresponder ao código executado, o depurador usa o editor normal. Se um rascunho não salvo for diferente, abre uma cópia somente leitura e preserva o rascunho. Salve alterações do módulo antes de outra sessão.",
		["debugInspectUnavailable"] = "Sem valor no escopo atual",
		["debugLimits"] = "O depurador usa cópias do código. Editar o script ativo para a depuração; os pontos de interrupção são preservados e ajustados às linhas alteradas. Apenas callbacks OnEvent registrados com :SetScript ou :HookScript entram na fila. Chamadas diretas a pcall/xpcall executam sem passos. Não é possível entrar em funções nativas; callbacks que precisam retornar de forma síncrona a uma função nativa, como os de ordenação, não podem pausar. Pausas não suportadas causam erros. Retornos instrumentados não preservam a otimização de chamadas de cauda de Lua.",
		["debugNoEvents"] = "Adicione primeiro um evento nas configurações do script.",
		["debugPaused"] = "Ponto de interrupção atingido",
		["debugProbeBindingsError"] = "Vínculo de variável de depuração inválido.",
		["debugProbeBindingsHelp"] = "Neste teste, o terceiro argumento opcional de breakpoint() expõe variáveis locais reais: { amount = { get = function() return amount end, set = function(value) amount = value end } }. O console lê por get e atribui por set. Sem set, a variável é somente leitura. Os vínculos valem apenas para o ponto e evento atuais; eventos na fila mantêm variáveis próprias. A captura automática de escopo e a instrumentação ainda não estão implementadas.",
		["debugProbeError"] = "Erro no teste do depurador",
		["debugProbeEvaluate"] = "Avaliar",
		["debugProbeFinished"] = "Execução concluída",
		["debugProbeHelp"] = "/lwdebug EVENT ativa o código atual; /lwdebug fire enfileira um evento de teste; /lwdebug step avança; /lwdebug stop cancela e limpa a fila. Use breakpoint(\"nome\", {valor=valor}) para capturar variáveis. F10 avança ao próximo ponto com este painel ou o editor ativo. Até 50 eventos aguardam em ordem. WoW continua e tabelas mantêm referências ativas. Passos automáticos por linha, F11, importações de módulos e pontos dentro de pcall/xpcall não são suportados. Valores secretos são ocultados na lista; textos secretos podem aparecer diretamente na dica.",
		["debugProbeInput"] = "Expressão ou código Lua",
		["debugProbeNotPaused"] = "Pare em um ponto de interrupção antes de avaliar código.",
		["debugProbeOverflow"] = "%d descartados",
		["debugProbePaused"] = "Ponto de interrupção atingido",
		["debugProbeQueue"] = "Na fila: %d",
		["debugProbeReadOnly"] = "Esta variável é somente leitura.",
		["debugProbeShow"] = "Mostrar código",
		["debugProbeSnapshot"] = "Código capturado (somente leitura)",
		["debugProbeStep"] = "Próximo ponto (F10)",
		["debugProbeStop"] = "Parar teste",
		["debugProbeTerminal"] = "Console de depuração",
		["debugProbeTerminalHelp"] = "O console de teste lê variáveis passadas a breakpoint() e o ambiente do script. Vínculos explícitos alteram variáveis locais reais; outras atribuições simples ficam no console. Mudanças em tabelas e chamadas de funções afetam o script.\n\nEnter: avaliar e limpar a entrada.\nAlt+Cima/Baixo: recuperar até 100 comandos.\n/lwdebug eval EXPRESSÃO também avalia código. Novas saídas rolam até o fim; 100 linhas são mantidas.\n\nErros mantêm a pausa. Valores secretos ficam ocultos.",
		["debugProbeTitle"] = "Teste do depurador",
		["debugProbeVariables"] = "Variáveis capturadas",
		["debugProbeWaiting"] = "Aguardando evento",
		["debugReadOnly"] = "Proteger o código durante a depuração",
		["debugScheduleAlways"] = "A cada login/recarga",
		["debugScheduleCancel"] = "Cancelar depuração agendada",
		["debugScheduleHelp"] = "Agende um script salvo pelo menu do depurador, uma vez ou a cada login. ADDON_LOADED se refere ao LuaWorkbench; PLAYER_LOGIN ao login. São usados código, módulos e pontos de interrupção salvos; rascunhos são preservados. O editor inicia minimizado sem assumir o foco. A execução automática normal é suspensa enquanto o depurador controla o script, mesmo se a compilação falhar. Parar libera o script, mas não cancela o agendamento recorrente. WoW continua rodando; addons carregados antes não podem ser depurados retroativamente.",
		["debugScheduleMenu"] = "Depurar após login/recarregar (código salvo)",
		["debugScheduleOnce"] = "Uma vez",
		["debugShow"] = "Ir à linha pausada",
		["debugSnapshot"] = "Código executado na depuração",
		["debugSnapshotHelp"] = "Esta visualização somente leitura mostra o código usado pelo depurador. Rascunhos não salvos no editor são preservados.",
		["debugSourceChanged"] = "A depuração parou porque o script mudou.",
		["debugStart"] = "Depurar script atual",
		["debugStepInto"] = "Entrar na função (F11)",
		["debugStepOver"] = "Avançar sem entrar (F10)",
		["debugStop"] = "Parar depuração (Shift+F5)",
		["debugTerminal"] = "Console de depuração",
		["debugTerminalHelp"] = "Durante uma pausa, avalie expressões ou código Lua. Atribuições alteram variáveis locais acessíveis; mudanças em tabelas e chamadas de funções afetam o script.\n\nEnter: avaliar e limpar a entrada.\nAlt+Cima/Baixo: recuperar comandos anteriores.\nNovas saídas rolam até o fim.\n\nErros mantêm a pausa. Valores secretos ficam ocultos no console; textos secretos podem aparecer na dica ao passar o cursor.",
		["debugTitle"] = "Depurador",
		["debugUnsupportedYield"] = "Esta chamada protegida ou nativa não pode pausar; a depuração parou.",
		["debugVariables"] = "Variáveis",
		["debugWaitingCallbacks"] = "Aguardando eventos do script",
		["debugWriteProtected"] = "Somente leitura durante a depuração",
		["debuggerBudgetExceeded"] = "A execução de depuração parou após passos demais.",
		["delete"] = "Excluir",
		["developerToolUnavailable"] = "Não foi possível carregar esta ferramenta de desenvolvimento da Blizzard.",
		["dirtyText"] = "Texto em vez do ponto não salvo",
		["errorDetails"] = "Detalhes do erro",
		["errorHistoryHelp"] = "Guarda até 100 erros recentes de scripts nesta sessão, incluindo execuções automáticas. Erros repetidos são agrupados com contagem e último horário. Recarregar apaga o histórico. Limpar a saída não apaga esta lista.",
		["eventAlreadyAdded"] = "Este evento já está na lista.",
		["eventName"] = "Nome do evento…",
		["eventTraceTool"] = "Mostrar ou ocultar Event Trace (/etrace). Verde: janela aberta.",
		["findCode"] = "Localizar no código",
		["font"] = "Fonte",
		["fontChat"] = "Bate-papo",
		["fontNumbers"] = "Números",
		["fontSize"] = "Tamanho da fonte",
		["fontStyle"] = "Estilo da fonte",
		["fontUI"] = "Interface",
		["frameStackTool"] = "Ativar ou desativar Frame Stack (/fstack). Verde: ativo.",
		["fullscreen"] = "Alternar tela cheia",
		["goToDefinition"] = "Ir para definição",
		["help"] = "Ajuda",
		["helpDebug"] = "print(...) escreve na saída. addon e editor se referem ao LuaWorkbench. Erros ficam na saída; o status é separado. Copiar saída seleciona o texto para Ctrl+C. O limite de linhas é configurável; há também um limite de 64.000 caracteres. A formatação é manual. As opções controlam fontes, recuo, parênteses, LF/CRLF e botão do minimapa. Após limpar a saída manualmente, você pode desfazer por 10 segundos. A saída adicionada depois é mantida ao restaurar; o limite configurado continua valendo.",
		["helpDump"] = "dump(...) escreve cada argumento separadamente na saída, preservando valores nil entre os argumentos e no final. dump({...}) mostra uma única tabela. Exemplo: dump(\"valor\", nil, false). DevTools_Dump(value, startKey) mantém a assinatura original; o segundo argumento opcional nomeia o valor exibido. Isso vale para execuções manuais e automáticas, módulos auxiliares e o terminal de depuração. Essas funções existem apenas no ambiente do script; as funções globais não mudam. Vários argumentos recebem os rótulos arg[1], arg[2] etc.; um único argumento fica sem número. O conteúdo das tabelas fica agrupado sob o respectivo rótulo. Use dump(...) para preservar argumentos nil: uma tabela criada com {...} não preserva a contagem completa dos argumentos.",
		["helpEditing"] = "Com foco no código ou na pesquisa: Ctrl+Enter executa, Ctrl+S salva, Ctrl+F pesquisa neste código, Ctrl+Shift+F em todos os nomes e códigos. F5 executa com foco ou ponteiro no editor; desative nas opções. Tab insere espaços, Shift+Tab remove recuo inicial. Na pesquisa: Enter / Shift+Enter seleciona o próximo / anterior resultado; Escape fecha a pesquisa de código. Ao renomear: Enter confirma, Escape cancela. Clique com o botão direito no código editável para formatar tudo ou inserir um trecho salvo ou uma importação de módulo no cursor atual. A navegação até definições está disponível apenas no editor principal. Shift+Alt+F formata o editor de código em foco, incluindo o editor de trechos. No editor principal: Ctrl+Espaço abre sugestões, Cima/Baixo seleciona, Enter / Tab insere e Esc fecha. A ajuda destaca o parâmetro atual. Alt+Cima/Baixo move a linha; Alt+Shift+Cima/Baixo duplica. Sem seleção, Ctrl+C/X copia/recorta a linha e Ctrl+V a insere acima da atual. As quebras de linha salvas seguem as opções. (macOS: ⌘C / ⌘X / ⌘V). Mac: Ctrl+Backspace apaga um caractere, Option+Backspace a palavra anterior e Cmd+Backspace até o início da linha. Mac: Option+Esquerda/Direita move por palavra; Cmd+Esquerda/Direita vai ao início/fim da linha. Use Shift para ampliar a seleção. Cmd+Cima/Baixo vai ao início/fim do código; use Shift para selecionar.",
		["helpSecretDump"] = "Dumps secretos no chat ficam desativados por padrão. Quando ativados, dump() e DevTools_Dump() também enviam o dump completo para a saída normal da Blizzard se o valor ou uma linha formatada for secreto. O editor mantém o marcador verde <secret>. Dumps comuns e print() não são encaminhados. Também se aplica às execuções automáticas; o que a Blizzard pode mostrar depende do cliente e das restrições de valores secretos.",
		["helpShortcuts"] = "Atalhos de teclado",
		["helpStorage"] = "Nomeie novos scripts diretamente na lista. Clique direito para renomear, mover, excluir ou restaurar a versão salva. O ponto indica alterações não salvas. Ctrl+S substitui a versão salva. Recuperar rascunhos após recarregar vem ativado e pode ser desativado nas opções. Restaurar descarta alterações após confirmação. As setas recolhem ou expandem pastas.",
		["helpTabDebug"] = "Depuração",
		["helpTabEditor"] = "Editor",
		["helpTabScripts"] = "Scripts e módulos",
		["helpTabShortcuts"] = "Atalhos",
		["helperConsumerHelp"] = "Em outro script, importe o módulo com um nome local. Uma função local pode ter o mesmo nome sem substituir a função do módulo:",
		["helperCycle"] = "Dependência circular entre módulos:",
		["helperDuplicate"] = "Este nome de módulo já está em uso:",
		["helperEnabled"] = "Disponibilizar como módulo auxiliar",
		["helperHelp"] = "Salve um script e disponibilize-o como módulo auxiliar nas configurações, com um nome exclusivo como MyTools. O nome do módulo é separado do título e não diferencia maiúsculas de minúsculas. Ele retorna uma tabela de funções ou valores e só é executado quando requireHelper solicita. Cada execução manual ou automática tem um cache novo; importações repetidas ou aninhadas compartilham a mesma tabela. Módulos ausentes, nomes duplicados, ciclos e retornos que não são tabelas geram erros. As variáveis ficam no ambiente interno; escrever em _G exige uma escolha explícita. Exemplo de módulo:",
		["helperInlineHelp"] = "Um módulo auxiliar deve terminar com return tools (ou outra tabela). Coloque nessa tabela as funções que deseja compartilhar. requireHelper retorna essa tabela para que outro script possa chamar suas funções. Sem retornar uma tabela, a importação falha. Apenas o código salvo é executado quando solicitado; ativar esta opção não o executa.",
		["helperInvalidName"] = "Comece com uma letra ou _; depois use letras, números, _, . ou - (máximo de 80 caracteres).",
		["helperLoadError"] = "Não foi possível carregar o módulo auxiliar",
		["helperMissing"] = "Nenhum módulo auxiliar ativado e salvo:",
		["helperModule"] = "Módulos auxiliares",
		["helperMustReturnTable"] = "O módulo auxiliar deve retornar uma tabela:",
		["helperName"] = "Nome exclusivo do módulo",
		["helperNameHelp"] = "Independente do título do script. Os nomes são exclusivos sem diferenciar maiúsculas. Pressione Enter para aplicar uma alteração.",
		["helperUsageExample"] = "Em outro script:",
		["hexColor"] = "Cor com seis dígitos hexadecimais (RRGGBB); Enter para aplicar.",
		["indentWidth"] = "Recuo (espaços)",
		["inspectorCopyPath"] = "Copiar caminho de acesso",
		["inspectorCopyValue"] = "Copiar valor",
		["inspectorInsert"] = "Inserir no código",
		["inspectorLimit"] = "Limite: primeiros 500 campos",
		["inspectorLocal"] = "Inserir como variável local",
		["inspectorOpen"] = "Abrir objeto",
		["inspectorParent"] = "Ir ao objeto pai",
		["inspectorPick"] = "Selecionar quadro",
		["inspectorPickHelp"] = "Alt esquerdo: próximo · Alt direito: anterior · Ctrl: inspecionar · Esc: cancelar",
		["inspectorRefresh"] = "Atualizar",
		["inspectorSearch"] = "Buscar campos e valores expandidos",
		["inspectorSession"] = "Referências duram até recarregar. Clique direito em uma linha para ver ações.",
		["inspectorTitle"] = "Inspetor de objetos",
		["inspectorTool"] = "LuaWorkbench: Inspetor de objetos — Selecionar quadro",
		["invalidEvent"] = "Evento do WoW desconhecido:",
		["knowledgeBase"] = "Base de conhecimento",
		["lineEnding"] = "Quebras de linha salvas",
		["loginDescription"] = "Executa em PLAYER_LOGIN, inclusive após recarregar a interface.",
		["manualRun"] = "Manual",
		["matchCase"] = "Diferenciar maiúsculas",
		["matchPosition"] = "%d de %d",
		["matches"] = "%d resultados",
		["maximizeCode"] = "Maximizar / restaurar código",
		["minimapHint"] = "Abrir ou restaurar o editor Lua",
		["minimapToggle"] = "Mostrar / ocultar botão do minimapa",
		["minimize"] = "Minimizar",
		["minimizedOutput"] = "Prévia da saída ao minimizar",
		["minimizedOutputHelp"] = "A prévia opcional abaixo da barra minimizada mostra uma quantidade configurável das últimas linhas novas. A altura se ajusta às linhas visíveis e o cabeçalho indica quantas são exibidas. Desaparece após alguns segundos; clique para restaurar o editor. Saídas em sequência são agrupadas e a saída completa permanece no editor. Desativada por padrão, com três linhas de prévia.",
