		["navigationBack"] = "Voltar",
		["navigationHelp"] = "F12 abre uma declaração local ou uma exportação de módulo identificável estaticamente. Alt+Esquerda volta ao script, cursor e rolagem anteriores. Variáveis locais, parâmetros e escopos são considerados. A navegação aceita aliases locais explícitos de requireHelper com nomes literais e exportações simples de tabelas. Não deduz chaves dinâmicas, definições geradas, metatabelas ou resoluções globais arbitrárias. Código grande ou incompleto é analisado de forma conservadora; não é um servidor de linguagem.",
