		["apiSearch"] = "Поиск по именам API, описаниям и параметрам",
		["apiStructures"] = "Структуры",
		["apiSystems"] = "Объекты / системы",
		["apiTypes"] = "Типы",
		["apiUnavailable"] = "Не удалось загрузить документацию API Blizzard. Откройте редактор снова, чтобы повторить попытку.",
		["autoIndent"] = "Автоматический отступ",
		["autoPairs"] = "Автозакрытие скобок и кавычек",
		["autoRunHelp"] = "Автозапуск использует сохранённый код, а не несохранённые изменения. Запуск при загрузке происходит один раз при загрузке LuaWorkbench (ADDON_LOADED), при входе — один раз по PLAYER_LOGIN, в том числе после перезагрузки интерфейса. Если включены оба, скрипт выполняется на обоих этапах. Пользовательское событие запускает его при каждом срабатывании, даже при закрытом редакторе. По умолчанию всё выключено; включение не запускает код немедленно.",
		["autocomplete"] = "Автодополнение и подсказки параметров",
		["autocompleteHelp"] = "Enter / Tab: вставить · Esc: закрыть · Ctrl+Пробел: подсказки",
		["automaticRun"] = "Автоматический запуск",
		["clearErrors"] = "Очистить ошибки",
		["clearOnRun"] = "Очищать при запуске",
		["clearOutputAction"] = "Очистить",
		["clearSearch"] = "Очистить поиск",
		["colorCall"] = "Вызовы функций",
		["colorComment"] = "Комментарии",
		["colorFunctionName"] = "Определения функций",
		["colorGlobalVariable"] = "Нелокальные имена",
		["colorIdentifier"] = "Имена / идентификаторы",
		["colorKeyword"] = "Ключевые слова",
		["colorLiteral"] = "true / false / nil",
		["colorLocalVariable"] = "Локальные переменные",
		["colorNumber"] = "Числа",
		["colorOperator"] = "Операторы",
		["colorParameter"] = "Параметры функций",
		["colorPunctuation"] = "Скобки и пунктуация",
		["colorString"] = "Строки",
		["confirmDelete"] = "Удалить этот скрипт?",
		["confirmRevert"] = "Отменить несохранённые изменения и восстановить последнюю сохранённую версию?",
		["copyOutputAction"] = "Копировать",
		["copyOutputHint"] = "Выделить текст, затем нажать Ctrl+C для копирования.",
		["cursorPosition"] = "Стр %d, Стлб %d",
		["customEventHelp"] = "Введите имя события WoW и нажмите Enter или + для добавления. Каждое событие можно отдельно включить или удалить. Недопустимые события отклоняются. В скрипте event содержит имя, а ... — аргументы. При загрузке передаются аргументы ADDON_LOADED. Сохраните скрипт перед автозапуском.",
		["customEvents"] = "Свои события",
		["customize"] = "Настроить…",
		["debugBreakpoint"] = "Переключить точку останова (F9)",
		["debugCallbackHelp"] = "Чтобы отладить обработчик OnEvent в коде, используйте :SetScript(\"OnEvent\", ...) или :HookScript(\"OnEvent\", ...), поставьте точку останова внутри обработчика и один раз запустите отладку текущего скрипта. После регистрации поступающие события выполняют обработчик в отладчике. Поддерживаются CreateFrame и _G.CreateFrame. Во время паузы ждут до 50 событий; при полной очереди новые отбрасываются, а аргументы nil сохраняются. При остановке прежний обработчик SetScript восстанавливается, если обработчик отладки ещё установлен. Перехватчики HookScript нельзя удалить, поэтому при остановке они становятся неактивными.",
		["debugClearBreakpoints"] = "Удалить точки останова",
		["debugContinue"] = "Продолжить (F5)",
		["debugDrawer"] = "Показать или скрыть консоль отладки",
		["debugEvents"] = "Отладить настроенные события",
		["debugEventsHelp"] = "Отладка событий ожидает включённые пользовательские события и PLAYER_LOGIN, если он настроен. Запуск и вход не воспроизводятся повторно. Чтобы проверить код сразу, выберите отладку текущего скрипта.",
		["debugHelp"] = "Щёлкните номер строки, чтобы переключить точку останова. Начните отладку кнопкой рядом с запуском или выберите настроенные события. F5 продолжает, F10 выполняет шаг с обходом, F11 заходит в функции скрипта, Shift+F5 останавливает. Консоль позволяет читать и менять локальные переменные в строке остановки. Наведите указатель на переменную в редакторе, чтобы увидеть значение. Новые события ждут в ограниченной очереди, пока WoW продолжает работать. Точки останова сохраняются для каждого скрипта после перезагрузки интерфейса и следуют за строками при добавлении или удалении текста. Метки на невыполняемых строках сохраняются, но не вызывают паузу; удаление целой строки кода может удалить её точку останова.",
		["debugHelperHelp"] = "F10 обходит вызовы модулей; F11 заходит в сохранённые модули, загруженные через requireHelper. Если код в редакторе совпадает с выполненным, используется обычный редактор. Если несохранённый черновик отличается, открывается снимок только для чтения, а черновик сохраняется. Сохраните изменения модуля перед новым сеансом.",
		["debugInspectUnavailable"] = "Нет значения в текущей области видимости",
		["debugLimits"] = "Отладчик использует снимки кода. Редактирование активного скрипта останавливает отладку; точки останова сохраняются и перемещаются с изменёнными строками. В очередь попадают только обработчики OnEvent, зарегистрированные через :SetScript или :HookScript. Прямые вызовы pcall/xpcall выполняются без шагов. Заход во встроенные функции невозможен; обратные вызовы, которые должны синхронно вернуть результат встроенной функции, например при сортировке, нельзя приостановить. Неподдерживаемые паузы вызывают ошибки. Инструментированные возвраты не сохраняют оптимизацию хвостовых вызовов Lua.",
		["debugNoEvents"] = "Сначала добавьте событие в настройках скрипта.",
		["debugPaused"] = "Точка останова достигнута",
		["debugProbeBindingsError"] = "Недопустимая привязка переменной отладчика.",
		["debugProbeBindingsHelp"] = "В этом тесте третий необязательный аргумент breakpoint() открывает доступ к настоящим локальным переменным: { amount = { get = function() return amount end, set = function(value) amount = value end } }. Консоль читает через get и присваивает через set. Без set переменная доступна только для чтения. Привязки действуют лишь для текущей точки и вызова события; события в очереди сохраняют собственные переменные. Автоматический захват области видимости и инструментирование ещё не реализованы.",
		["debugProbeError"] = "Ошибка теста отладчика",
		["debugProbeEvaluate"] = "Вычислить",
		["debugProbeFinished"] = "Выполнение завершено",
		["debugProbeHelp"] = "/lwdebug EVENT активирует текущий код; /lwdebug fire добавляет тестовое событие; /lwdebug step продолжает; /lwdebug stop отменяет и очищает очередь. Используйте breakpoint(\"имя\", {value=value}) для захвата переменных. F10 переходит к следующей точке, когда эта панель или редактор активны. До 50 событий ожидают по порядку. WoW продолжает работу; таблицы остаются живыми ссылками. Автоматические шаги по строкам, F11, импорт модулей и точки внутри pcall/xpcall не поддерживаются. Секретные значения скрыты в списке; секретные строки могут отображаться непосредственно в подсказке.",
		["debugProbeInput"] = "Выражение или код Lua",
		["debugProbeNotPaused"] = "Остановитесь на точке останова перед вычислением кода.",
		["debugProbeOverflow"] = "Отброшено: %d",
		["debugProbePaused"] = "Точка останова достигнута",
		["debugProbeQueue"] = "В очереди: %d",
		["debugProbeReadOnly"] = "Эта переменная доступна только для чтения.",
		["debugProbeShow"] = "Показать код",
		["debugProbeSnapshot"] = "Захваченный код (только чтение)",
		["debugProbeStep"] = "Следующая точка (F10)",
		["debugProbeStop"] = "Остановить тест",
		["debugProbeTerminal"] = "Консоль отладки",
		["debugProbeTerminalHelp"] = "Тестовая консоль читает переменные, переданные в breakpoint(), и окружение скрипта. Явные привязки меняют настоящие локальные переменные; остальные простые присваивания остаются в консоли. Изменения таблиц и вызовы функций влияют на скрипт.\n\nEnter: вычислить и очистить ввод.\nAlt+Вверх/Вниз: вызвать до 100 предыдущих команд.\n/lwdebug eval ВЫРАЖЕНИЕ также вычисляет код. Новый вывод прокручивается вниз; сохраняются 100 строк.\n\nОшибки сохраняют паузу. Секретные значения скрыты.",
		["debugProbeTitle"] = "Тест отладчика",
		["debugProbeVariables"] = "Захваченные переменные",
		["debugProbeWaiting"] = "Ожидание события",
		["debugReadOnly"] = "Защищать код от изменений при отладке",
		["debugScheduleAlways"] = "При каждом входе/перезагрузке",
		["debugScheduleCancel"] = "Отменить запланированную отладку",
		["debugScheduleHelp"] = "Запланируйте один сохранённый скрипт через меню отладчика: однократно или при каждом входе. ADDON_LOADED означает загрузку LuaWorkbench, PLAYER_LOGIN — вход в игру. Используются сохранённые код, модули и точки останова; черновики сохраняются. Редактор запускается свёрнутым без захвата фокуса. Обычный автоматический запуск блокируется, пока отладчик управляет скриптом, даже при ошибке компиляции. Остановка освобождает скрипт, но не отменяет повторяющееся расписание. WoW продолжает работать; ранее загруженные аддоны нельзя отладить задним числом.",
		["debugScheduleMenu"] = "Отладка после входа/перезагрузки (сохранённый код)",
		["debugScheduleOnce"] = "Один раз",
		["debugShow"] = "Перейти к строке остановки",
		["debugSnapshot"] = "Код, выполненный отладчиком",
		["debugSnapshotHelp"] = "Этот режим только для чтения показывает код, используемый отладчиком. Несохранённые черновики редактора сохраняются.",
		["debugSourceChanged"] = "Отладка остановлена, поскольку скрипт изменился.",
		["debugStart"] = "Отладить текущий скрипт",
		["debugStepInto"] = "Шаг с заходом (F11)",
		["debugStepOver"] = "Шаг с обходом (F10)",
		["debugStop"] = "Остановить отладку (Shift+F5)",
		["debugTerminal"] = "Консоль отладки",
		["debugTerminalHelp"] = "Во время паузы вычисляйте выражения или код Lua. Присваивания меняют доступные локальные переменные; изменения таблиц и вызовы функций влияют на скрипт.\n\nEnter: вычислить и очистить ввод.\nAlt+Вверх/Вниз: вызвать предыдущие команды.\nНовый вывод прокручивается вниз.\n\nОшибки сохраняют паузу. Секретные значения скрыты в консоли; секретные строки могут появляться в подсказке при наведении.",
		["debugTitle"] = "Отладчик",
		["debugUnsupportedYield"] = "Этот защищённый или встроенный вызов нельзя приостановить; отладка остановлена.",
		["debugVariables"] = "Переменные",
		["debugWaitingCallbacks"] = "Ожидание событий скрипта",
		["debugWriteProtected"] = "Только чтение при отладке",
		["debuggerBudgetExceeded"] = "Отладка остановлена после слишком большого числа шагов.",
		["delete"] = "Удалить",
		["developerToolUnavailable"] = "Не удалось загрузить этот инструмент разработчика Blizzard.",
		["dirtyText"] = "Текст вместо точки изменений",
		["errorDetails"] = "Подробности ошибки",
		["errorHistoryHelp"] = "Хранит до 100 недавних ошибок скриптов за сессию, включая автозапуски. Повторы объединяются со счётчиком и последним временем. Перезагрузка интерфейса очищает историю. Очистка вывода не очищает этот список.",
		["eventAlreadyAdded"] = "Это событие уже есть в списке.",
		["eventName"] = "Введите имя события…",
		["eventTraceTool"] = "Показать или скрыть Event Trace (/etrace). Зелёный: окно открыто.",
		["findCode"] = "Поиск в коде",
		["font"] = "Шрифт",
		["fontChat"] = "Чат",
		["fontNumbers"] = "Цифры",
		["fontSize"] = "Размер шрифта",
		["fontStyle"] = "Стиль шрифта",
		["fontUI"] = "Интерфейс",
		["frameStackTool"] = "Включить или выключить Frame Stack (/fstack). Зелёный: включён.",
		["fullscreen"] = "Переключить полноэкранный режим",
		["goToDefinition"] = "Перейти к определению",
		["help"] = "Справка",
		["helpDebug"] = "print(...) выводит текст. addon и editor указывают на LuaWorkbench. Ошибки остаются в выводе, статус показан отдельно. Копирование вывода выделяет текст для Ctrl+C. Число строк настраивается; также действует предел 64 000 символов. Форматирование запускается вручную. В настройках доступны шрифты, отступы, скобки, LF/CRLF и кнопка миникарты. После ручной очистки вывод можно восстановить в течение 10 секунд. Добавленный после очистки вывод сохраняется; настроенное ограничение объёма продолжает действовать.",
		["helpDump"] = "dump(...) выводит каждый аргумент отдельно, сохраняя nil между аргументами и в конце. dump({...}) выводит одну таблицу. Пример: dump(\"значение\", nil, false). DevTools_Dump(value, startKey) сохраняет исходную сигнатуру; необязательный второй аргумент задаёт имя выводимого значения. Это действует при ручном и автоматическом запуске, в модулях помощников и терминале отладки. Эти функции существуют только в окружении скрипта; глобальные функции не меняются. Несколько аргументов помечаются как arg[1], arg[2] и т. д.; единственный аргумент не нумеруется. Содержимое таблиц группируется под именем соответствующего аргумента. Используйте dump(...) для сохранения аргументов nil: таблица, созданная через {...}, не сохраняет полное число аргументов.",
		["helpEditing"] = "При фокусе в коде или поиске: Ctrl+Enter выполняет код, Ctrl+S сохраняет, Ctrl+F ищет в текущем коде, Ctrl+Shift+F — во всех названиях и коде. F5 запускает код, если редактор имеет фокус или указатель находится над ним; отключается в настройках. Tab вставляет пробелы, Shift+Tab уменьшает начальный отступ. В поиске: Enter / Shift+Enter выбирает следующее / предыдущее совпадение; Escape закрывает поиск в коде. При переименовании: Enter подтверждает, Escape отменяет. Щёлкните правой кнопкой в редактируемом коде, чтобы отформатировать весь код или вставить сохранённый фрагмент либо импорт модуля в текущую позицию курсора. Переход к определениям доступен только в основном редакторе. Shift+Alt+F форматирует активный редактор кода, включая редактор фрагментов. В основном редакторе: Ctrl+Пробел открывает подсказки, вверх/вниз выбирает, Enter / Tab вставляет, Esc закрывает. Подсказка параметров выделяет текущий аргумент. Alt+вверх/вниз перемещает строку, Alt+Shift+вверх/вниз дублирует её. Без выделения Ctrl+C/X копирует/вырезает строку, Ctrl+V вставляет её выше текущей. Окончания строк при сохранении соответствуют настройкам. (macOS: ⌘C / ⌘X / ⌘V). Mac: Ctrl+Backspace удаляет один символ, Option+Backspace — предыдущее слово, Cmd+Backspace — текст до начала строки. Mac: Option+влево/вправо перемещает по словам, Cmd+влево/вправо — в начало/конец строки. Shift расширяет выделение. Cmd+вверх/вниз перемещает в начало/конец кода; Shift выделяет текст до этой позиции.",
		["helpSecretDump"] = "По умолчанию отключено. Если включено, dump() и DevTools_Dump() дополнительно отправляют весь дамп в стандартный вывод Blizzard, когда значение или отформатированная строка являются секретными. В редакторе остаётся зелёная метка <secret>. Обычные дампы и print() не перенаправляются. Работает и при автоматическом запуске; доступное отображение зависит от клиента и ограничений секретных значений.",
		["helpShortcuts"] = "Сочетания клавиш",
		["helpStorage"] = "Название нового скрипта вводится прямо в списке. Правая кнопка: переименовать, переместить, удалить или восстановить сохранённую версию. Точка означает несохранённые изменения. Ctrl+S заменяет сохранённую версию. Восстановление черновиков после перезагрузки включено по умолчанию и отключается в настройках. Возврат к сохранённому удаляет изменения после подтверждения. Стрелки сворачивают и разворачивают папки.",
		["helpTabDebug"] = "Отладка",
		["helpTabEditor"] = "Редактор",
		["helpTabScripts"] = "Скрипты и модули",
		["helpTabShortcuts"] = "Сочетания клавиш",
		["helperConsumerHelp"] = "В другом скрипте импортируйте модуль под локальным именем. Ваша локальная функция может иметь такое же имя, не заменяя функцию модуля:",
		["helperCycle"] = "Циклическая зависимость модулей:",
		["helperDuplicate"] = "Это имя модуля уже используется:",
		["helperEnabled"] = "Предоставить как вспомогательный модуль",
		["helperHelp"] = "Сохраните скрипт и включите его как модуль в настройках, задав уникальное имя, например MyTools. Имя модуля отдельно от названия скрипта; различия в регистре не учитываются. Модуль возвращает таблицу функций или значений и выполняется только по запросу requireHelper. Каждый ручной или автоматический запуск получает новый кеш; повторные и вложенные импорты используют одну таблицу. Отсутствующие модули, повторяющиеся имена, циклы и возврат не таблицы вызывают ошибки. Переменные остаются во внутреннем окружении; запись в _G требует явного указания. Пример модуля:",
		["helperInlineHelp"] = "В конце вспомогательного модуля должен быть return tools (или возврат другой таблицы). Поместите в эту таблицу функции, которыми хотите поделиться. requireHelper возвращает эту таблицу, чтобы другой скрипт мог вызывать её функции. Без возврата таблицы импорт завершится ошибкой. По запросу выполняется только сохранённый код; включение этой опции не запускает его.",
		["helperInvalidName"] = "Начните с буквы или _, затем используйте буквы, цифры, _, . или - (не более 80 символов).",
		["helperLoadError"] = "Не удалось загрузить модуль",
		["helperMissing"] = "Нет включённого сохранённого модуля:",
		["helperModule"] = "Вспомогательные модули",
		["helperMustReturnTable"] = "Модуль должен возвращать таблицу:",
		["helperName"] = "Уникальное имя модуля",
		["helperNameHelp"] = "Не зависит от названия скрипта. Имена уникальны без учёта регистра. Нажмите Enter, чтобы применить новое имя.",
		["helperUsageExample"] = "В другом скрипте:",
