		["minimize"] = "Свернуть",
		["minimizedOutput"] = "Показывать новый вывод при сворачивании",
		["minimizedOutputHelp"] = "Необязательный предпросмотр под свёрнутой панелью показывает настраиваемое число последних новых строк. Высота подстраивается под видимые строки, а заголовок указывает их количество. Через несколько секунд предпросмотр исчезает; нажмите, чтобы открыть редактор. Частый вывод группируется, а полный текст остаётся в редакторе. По умолчанию отключён, число строк предпросмотра — три.",
		["minimizedOutputLines"] = "Строки свёрнутого предпросмотра",
		["monochrome"] = "Монохромный контур",
		["moveTo"] = "Переместить в папку…",
		["navigationBack"] = "Назад",
		["navigationHelp"] = "F12 открывает локальное объявление либо статически распознаваемый экспорт модуля. Alt+Влево возвращает предыдущий скрипт, положение курсора и прокрутку. Учитываются локальные переменные, параметры и области видимости. Навигация поддерживает явные локальные псевдонимы requireHelper со строковым именем и простые экспорты таблиц. Динамические ключи, созданные во время выполнения определения, метатаблицы и произвольные глобальные ссылки не выводятся. Большой или незавершённый код анализируется осторожно; это не языковой сервер.",
