		["outputWindowHelp"] = "Выберите расположение в Настройки > Вывод или в меню окна вывода. Перетаскивание за заголовок доступно только в режиме Плавающее. У закреплённого окна можно лишь менять размер за правый нижний угол. Закреплённое окно следует за редактором; положение и размер сохраняются. Выберите Встроенное, чтобы вернуть его в редактор.",
