		["scriptSettingsHelp"] = "Шестерёнка рядом с именем открывает настройки скрипта. Синий значок в списке показывает активные триггеры; нажатие открывает настройки этого скрипта. Точка несохранённых изменений независима. Автозапуск и очистка вывода перед запуском настраиваются для каждого скрипта.",
