		["autoPairs"] = "自动闭合括号和引号",
		["autoRunHelp"] = "自动运行使用已保存的代码，不使用未保存的修改。启动时运行在 LuaWorkbench 加载时（ADDON_LOADED）执行一次；登录时运行在 PLAYER_LOGIN 时执行一次，也包括重载界面。两项都启用时会在两个阶段分别执行。自定义事件每次发生都会执行脚本，即使编辑器已关闭。所有选项默认关闭，启用时不会立即运行代码。",
		["autocomplete"] = "代码补全和参数提示",
