		["copyOutputAction"] = "复制",
		["copyOutputHint"] = "选中文本后，按 Ctrl+C 复制。",
		["cursorPosition"] = "行 %d，列 %d",
		["customEventHelp"] = "输入 WoW 事件名称，按回车或 + 添加。每个事件都可单独启用或移除；无效事件会被拒绝。脚本中的 event 是名称，... 是参数。启动运行会传入 ADDON_LOADED 的参数。自动运行前请保存脚本。",
		["customEvents"] = "自定义事件",
		["customize"] = "自定义…",
		["debugBreakpoint"] = "切换断点 (F9)",
		["debugCallbackHelp"] = "要调试代码中的 OnEvent 处理函数，请使用 :SetScript(\"OnEvent\", ...) 或 :HookScript(\"OnEvent\", ...)，在回调内设置断点，然后启动一次“调试当前脚本”。注册后，传入事件会在调试器中执行回调。CreateFrame 和 _G.CreateFrame 均可使用。暂停期间最多排队 50 个事件；队列满时丢弃新事件，nil 参数会保留。停止时，若调试处理函数仍已安装，则恢复先前的 SetScript 处理函数。HookScript 钩子无法移除，停止后会失效。",
		["debugClearBreakpoints"] = "清除断点",
		["debugContinue"] = "继续 (F5)",
		["debugDrawer"] = "显示或隐藏调试控制台",
		["debugEvents"] = "调试已配置的事件",
		["debugEventsHelp"] = "事件调试等待已启用的自定义事件，以及已配置的 PLAYER_LOGIN。它不会重放启动或登录。使用“调试当前脚本”可立即测试代码。",
		["debugHelp"] = "单击行号可切换断点。通过“运行”旁的调试按钮开始，或选择已配置的事件。F5 继续，F10 单步跳过，F11 进入脚本函数，Shift+F5 停止。在暂停行可用控制台读取和修改局部变量。将鼠标悬停在编辑器中的变量上可查看其值。WoW 继续运行，新事件在容量有限的队列中等待。 断点按脚本保存，重载后仍保留，并在插入或删除文本时跟随对应行移动。不可执行行的标记会保留，但不会暂停执行；删除整行代码可能移除该行的断点。",
		["debugHelperHelp"] = "F10 跳过辅助模块调用；F11 进入通过 requireHelper 加载的已保存辅助模块。如果编辑器内容与执行的代码一致，调试器使用普通编辑器。如果未保存的草稿不同，则打开只读快照并保留草稿。请在新会话前保存辅助模块的修改。",
		["debugInspectUnavailable"] = "当前作用域中没有值",
		["debugLimits"] = "调试器使用代码快照。编辑当前脚本会停止调试；断点会保留并随修改后的行调整。仅通过 :SetScript 或 :HookScript 注册的 OnEvent 回调会排队。直接调用 pcall/xpcall 时不进行单步执行。无法单步进入原生函数；必须同步返回原生函数的回调（如排序回调）无法暂停。不受支持的暂停会导致错误。插桩后的返回语句不保留 Lua 的尾调用优化。",
		["debugNoEvents"] = "请先在脚本设置中添加事件。",
		["debugPaused"] = "已到达断点",
		["debugProbeBindingsError"] = "无效的调试变量绑定。",
		["debugProbeBindingsHelp"] = "本测试中，breakpoint() 的可选第三个参数可公开真实局部变量：{ amount = { get = function() return amount end, set = function(value) amount = value end } }。控制台通过 get 读取、通过 set 赋值。没有 set 时变量只读。绑定仅适用于当前断点和事件调用；排队事件保留各自的局部变量。尚未实现自动作用域捕获和代码插桩。",
		["debugProbeError"] = "调试测试错误",
		["debugProbeEvaluate"] = "求值",
		["debugProbeFinished"] = "运行完成",
		["debugProbeHelp"] = "/lwdebug EVENT 启用当前代码；/lwdebug fire 加入测试事件；/lwdebug step 继续；/lwdebug stop 中止并清空队列。用 breakpoint(\"名称\", {value=value}) 捕获变量。此面板或编辑器激活时，F10 前进到下一断点。最多 50 个事件按顺序等待。WoW 继续运行，表仍是实时引用。不支持自动逐行步进、F11、模块导入或 pcall/xpcall 内的断点。秘密值在列表中隐藏；秘密字符串可直接显示在提示框中。",
		["debugProbeInput"] = "表达式或 Lua 代码",
		["debugProbeNotPaused"] = "请先在断点暂停，再执行求值。",
		["debugProbeOverflow"] = "已丢弃 %d 个",
		["debugProbePaused"] = "已到达断点",
		["debugProbeQueue"] = "排队：%d",
		["debugProbeReadOnly"] = "此变量只读。",
		["debugProbeShow"] = "查看代码",
		["debugProbeSnapshot"] = "捕获的代码（只读）",
		["debugProbeStep"] = "下一断点 (F10)",
		["debugProbeStop"] = "停止测试",
		["debugProbeTerminal"] = "调试控制台",
		["debugProbeTerminalHelp"] = "测试控制台读取传入 breakpoint() 的变量和脚本环境。显式绑定会修改真实局部变量；其他简单赋值仅影响控制台。修改表和调用函数会影响脚本。\n\n回车：求值并清空输入。\nAlt+上/下方向键：调出最多 100 条历史命令。\n也可使用 /lwdebug eval 表达式 求值。新输出自动滚动到底部，保留 100 行。\n\n出错后仍保持暂停。秘密值会隐藏。",
		["debugProbeTitle"] = "调试器测试",
		["debugProbeVariables"] = "捕获的变量",
		["debugProbeWaiting"] = "等待事件",
		["debugReadOnly"] = "调试时保护代码不被修改",
		["debugScheduleAlways"] = "每次登录/重载",
		["debugScheduleCancel"] = "取消预定调试",
		["debugScheduleHelp"] = "在调试器菜单中为一个已保存脚本预定下次登录/重载时调试，默认仅一次，也可每次执行。ADDON_LOADED 指 LuaWorkbench 自身加载；PLAYER_LOGIN 指登录。使用已保存的代码、辅助模块和断点，保留未保存草稿。编辑器以最小化方式启动且不获取焦点。调试器接管脚本期间会阻止普通自动执行，包括编译失败时。停止可解除接管，但不会取消重复预定。WoW 继续运行，无法追溯调试更早加载的插件。",
		["debugScheduleMenu"] = "登录/重载后调试（已保存代码）",
		["debugScheduleOnce"] = "仅一次",
		["debugShow"] = "跳转到暂停行",
