		["debugStop"] = "停止调试 (Shift+F5)",
		["debugTerminal"] = "调试控制台",
		["debugTerminalHelp"] = "暂停时可求值表达式或 Lua 代码。赋值会修改可访问的局部变量；修改表和调用函数会影响运行中的脚本。\n\n回车：求值并清空输入。\nAlt+上/下方向键：调出历史命令。\n新输出自动滚动到底部。\n\n出错后仍保持暂停。秘密值在控制台中隐藏；秘密字符串可显示在悬停提示中。",
