		["delete"] = "删除",
		["developerToolUnavailable"] = "无法加载此暴雪开发者工具。",
		["dirtyText"] = "以文字代替未保存圆点",
		["errorDetails"] = "错误详情",
		["errorHistoryHelp"] = "保留本次会话最近最多 100 条脚本错误，包括自动运行错误。重复错误合并显示次数和最近时间。重载界面会清空记录。清空输出不会清空此列表。",
		["eventAlreadyAdded"] = "该事件已在列表中。",
