		["eventTraceTool"] = "显示或隐藏事件追踪（/etrace）。绿色：窗口已打开。",
		["findCode"] = "在代码中查找",
		["font"] = "字体",
		["fontChat"] = "聊天",
		["fontNumbers"] = "数字",
		["fontSize"] = "字号",
		["fontStyle"] = "字体样式",
		["fontUI"] = "界面",
		["frameStackTool"] = "切换框体堆栈（/fstack）。绿色：已启用。",
		["fullscreen"] = "切换窗口全屏",
		["goToDefinition"] = "转到定义",
		["help"] = "帮助",
		["helpDebug"] = "print(...) 写入输出。addon 和 editor 指向 LuaWorkbench。错误保留在输出中，执行状态单独显示。复制输出会选中文本以便 Ctrl+C。可设置输出行数，同时限制最多 64,000 个字符。代码格式化仅手动执行。选项可设置字体、缩进、括号补全、LF/CRLF 和小地图按钮。 手动清空输出后，可在 10 秒内撤销。恢复时会保留之后新增的输出；设置的输出上限仍然有效。",
		["helpDump"] = "dump(...) 会逐个输出所有参数，包括参数之间及末尾的 nil。dump({...}) 则输出一个表。例如：dump(\"值\", nil, false)。DevTools_Dump(value, startKey) 保留原有调用格式；可选的第二个参数用于命名输出的值。此行为适用于手动运行、自动运行、辅助模块和调试终端。这些函数仅存在于脚本环境中，不会修改全局函数。 多个参数会标为 arg[1]、arg[2] 等；单个参数不编号。表的内容归于对应的参数标签下。要保留 nil 参数，请使用 dump(...)：用 {...} 创建的表无法保留完整的参数数量。",
		["helpEditing"] = "焦点在代码或搜索框内时：Ctrl+Enter 运行，Ctrl+S 保存，Ctrl+F 搜索当前代码，Ctrl+Shift+F 搜索所有脚本名称和代码。编辑器获得焦点或鼠标位于其上时，F5 运行代码，可在选项中关闭。Tab 插入空格，Shift+Tab 减少行首缩进。搜索中 Enter / Shift+Enter 选择下一个 / 上一个结果，Escape 关闭代码搜索。重命名时 Enter 确认，Escape 取消。 右键点击可编辑代码，可格式化全部代码，或在当前光标处插入已保存的代码片段或模块导入。仅主编辑器支持跳转到定义。Shift+Alt+F 可格式化当前获得焦点的代码编辑器，也适用于代码片段编辑器。 主编辑器：Ctrl+空格打开建议，上下键选择，Enter / Tab插入，Esc关闭。参数提示会标记当前参数。Alt+上下键移动当前行，Alt+Shift+上下键复制当前行。未选择文本时，Ctrl+C/X复制或剪切当前行，Ctrl+V在当前行上方插入复制的行。保存时使用选项中的换行格式。 (macOS: ⌘C / ⌘X / ⌘V). Mac：Ctrl+Backspace 删除一个字符，Option+Backspace 删除前一个单词，Cmd+Backspace 删除到行首。 Mac：Option+左右方向键按单词移动，Cmd+左右方向键跳到行首或行尾。加按 Shift 可扩展选择。 Cmd+上下方向键跳到代码开头或结尾；加按 Shift 可选择到该位置。",
		["helpSecretDump"] = "默认关闭。启用后，如果值或格式化后的某一行是秘密值，dump() 和 DevTools_Dump() 会将整个转储同时发送到暴雪的常规输出。编辑器仍保留绿色 <secret> 标记。普通转储和 print() 不会转发。自动运行时也适用；暴雪能够显示的内容取决于客户端及其秘密值限制。",
		["helpShortcuts"] = "键盘快捷键",
		["helpStorage"] = "直接在列表中为新脚本命名。右键可重命名、移动、删除或恢复已保存版本。圆点表示未保存的更改。Ctrl+S 替换已保存版本。重载后恢复草稿默认启用，可在选项中关闭。恢复已保存版本会在确认后放弃更改。文件夹箭头可折叠或展开内容。",
		["helpTabDebug"] = "调试",
		["helpTabEditor"] = "编辑器",
		["helpTabScripts"] = "脚本与模块",
		["helpTabShortcuts"] = "快捷键",
		["helperConsumerHelp"] = "在其他脚本中，用局部名称导入辅助模块。你可以定义同名的局部函数，而不会替换辅助模块中的函数：",
		["helperCycle"] = "辅助模块循环依赖：",
		["helperDuplicate"] = "此模块名已被使用：",
		["helperEnabled"] = "设为辅助模块",
		["helperHelp"] = "保存脚本，在其设置中将其设为辅助模块，并指定 MyTools 等唯一名称。模块名与显示标题无关，仅大小写不同也视为重名。模块返回包含函数或值的表，仅在 requireHelper 请求时运行。每次手动或自动运行都有独立的新缓存；同一次运行中重复或嵌套导入共享同一个表。模块缺失、重名、循环依赖或返回非表值都会报错。变量保留在内部环境中，写入 _G 必须显式指定。辅助模块示例：",
		["helperInlineHelp"] = "辅助模块必须在末尾使用 return tools 返回一个表（也可以返回其他表）。将要共享的函数放入这个表中。requireHelper 会返回该表，其他脚本通过它调用函数。如果没有返回表，导入就会失败。只有在请求时才会运行已保存的代码；启用此选项不会立即执行代码。",
		["helperInvalidName"] = "以英文字母或 _ 开头，随后可使用英文字母、数字、_、. 或 -（最多 80 个字符）。",
		["helperLoadError"] = "无法加载辅助模块",
