		["minimizedOutput"] = "最小化时预览新输出",
		["minimizedOutputHelp"] = "最小化栏下方的可选预览会显示可配置数量的最新输出行。高度随可见行数自动调整，标题显示已显示的行数。几秒后淡出，点击可恢复编辑器。连续输出会合并显示，完整输出仍保留在编辑器中。默认关闭，预览行数默认为三行。",
