		["moveTo"] = "移至文件夹…",
		["navigationBack"] = "返回",
		["navigationHelp"] = "F12 可打开局部声明或静态可识别的辅助模块导出。Alt+左箭头返回之前的脚本、光标和滚动位置。会考虑局部变量、参数和作用域。支持使用字面名称调用 requireHelper 的显式局部别名，以及简单的表导出。不推断动态键、运行时生成的定义、元表或任意全局引用。对大型或未完成代码采取保守分析；这不是语言服务器。",
