		["debugCallbackHelp"] = "若要偵錯程式碼中的 OnEvent 處理函式，請使用 :SetScript(\"OnEvent\", ...) 或 :HookScript(\"OnEvent\", ...)，在回呼內設定中斷點，然後啟動一次「偵錯目前腳本」。註冊後，傳入事件會在偵錯器中執行回呼。CreateFrame 和 _G.CreateFrame 均可使用。暫停期間最多排隊 50 個事件；佇列已滿時捨棄新事件，nil 引數會保留。停止時，若偵錯處理函式仍已安裝，則還原先前的 SetScript 處理函式。HookScript 掛鉤無法移除，停止後會失效。",
