		["debugHelp"] = "按一下行號可切換中斷點。透過「執行」旁的偵錯按鈕開始，或選擇已設定的事件。F5 繼續，F10 逐步執行，F11 進入腳本函式，Shift+F5 停止。在暫停行可用主控台讀取和修改區域變數。將滑鼠停在編輯器中的變數上即可查看其值。WoW 繼續執行，新事件在容量有限的佇列中等待。 中斷點依腳本儲存，重新載入後仍保留，並在插入或刪除文字時跟隨對應行移動。不可執行行的標記會保留，但不會暫停執行；刪除整行程式碼可能移除該行的中斷點。",
		["debugHelperHelp"] = "F10 略過輔助模組呼叫；F11 進入透過 requireHelper 載入的已儲存輔助模組。如果編輯器內容與執行的程式碼相同，偵錯器使用一般編輯器。如果未儲存的草稿不同，則開啟唯讀快照並保留草稿。請在新工作階段前儲存輔助模組的修改。",
