		["help"] = "說明",
		["helpDebug"] = "print(...) 寫入輸出。addon 和 editor 指向 LuaWorkbench。錯誤保留在輸出中，執行狀態單獨顯示。複製輸出會選取文字以便 Ctrl+C。可設定輸出行數，同時限制最多 64,000 個字元。程式碼格式化僅手動執行。選項可設定字型、縮排、括號補全、LF/CRLF 和小地圖按鈕。 手動清除輸出後，可在 10 秒內復原。還原時會保留之後新增的輸出；設定的輸出上限仍然有效。",
		["helpDump"] = "dump(...) 會逐一輸出所有參數，包括參數之間及末尾的 nil。dump({...}) 則輸出一個資料表。例如：dump(\"值\", nil, false)。DevTools_Dump(value, startKey) 保留原有呼叫格式；選用的第二個參數用於命名輸出的值。此行為適用於手動執行、自動執行、輔助模組和除錯終端。這些函式僅存在於腳本環境中，不會修改全域函式。 多個參數會標為 arg[1]、arg[2] 等；單一參數不編號。資料表的內容歸於對應的參數標籤下。若要保留 nil 參數，請使用 dump(...)：以 {...} 建立的資料表無法保留完整的參數數量。",
		["helpEditing"] = "焦點在程式碼或搜尋框內時：Ctrl+Enter 執行，Ctrl+S 儲存，Ctrl+F 搜尋目前程式碼，Ctrl+Shift+F 搜尋所有腳本名稱和程式碼。編輯器取得焦點或滑鼠位於其上時，F5 執行程式碼，可在選項中關閉。Tab 插入空格，Shift+Tab 減少行首縮排。搜尋中 Enter / Shift+Enter 選擇下一個 / 上一個結果，Escape 關閉程式碼搜尋。重新命名時 Enter 確認，Escape 取消。 在可編輯程式碼中按右鍵，可格式化全部程式碼，或在目前游標處插入已儲存的程式碼片段或模組匯入。只有主編輯器支援跳至定義。Shift+Alt+F 可格式化目前取得焦點的程式碼編輯器，也適用於程式碼片段編輯器。 主編輯器：Ctrl+空格開啟建議，上下鍵選擇，Enter / Tab插入，Esc關閉。參數提示會標示目前參數。Alt+上下鍵移動目前行，Alt+Shift+上下鍵複製目前行。未選取文字時，Ctrl+C/X複製或剪下目前行，Ctrl+V在目前行上方插入複製的行。儲存時使用選項中的換行格式。 (macOS: ⌘C / ⌘X / ⌘V). Mac：Ctrl+Backspace 刪除一個字元，Option+Backspace 刪除前一個單字，Cmd+Backspace 刪除至行首。 Mac：Option+左右方向鍵按單字移動，Cmd+左右方向鍵跳到行首或行尾。加按 Shift 可延伸選取範圍。 Cmd+上下方向鍵跳到程式碼開頭或結尾；加按 Shift 可選取至該位置。",
		["helpSecretDump"] = "預設關閉。啟用後，如果值或格式化後的某一行是秘密值，dump() 和 DevTools_Dump() 會將整個傾印同時傳送到暴雪的一般輸出。編輯器仍保留綠色 <secret> 標記。一般傾印和 print() 不會轉送。自動執行時也適用；暴雪能顯示的內容取決於用戶端及其秘密值限制。",
